#ifndef PATH_H
#define PATH_H

#include <string>
#include <vector>

namespace Path {
    /** Replace backslashes with forward slashes. */
    std::string toNativeSeparators(std::string path);

    /** Remove "./" and resolve "dir/../" parts. */
    std::string simplify(std::string path);

    /** Lower case extension including the dot, empty when there is none. */
    std::string getExtension(const std::string& path, bool lowercase = true);

    /** Everything up to and including the last '/'. Empty when path has no directory. */
    std::string getPath(const std::string& path);

    /** Everything after the last '/'. */
    std::string getFilename(const std::string& path);

    bool isDirectory(const std::string& path);
    bool isFile(const std::string& path);
    bool exists(const std::string& path);

    /** File size in bytes, 0 when it cannot be determined. */
    long long fileSize(const std::string& path);

    /** True when the extension marks a file that cppcheck accepts as input. */
    bool acceptFile(const std::string& path);

    /** True when the extension indicates C++ (as opposed to C) source. */
    bool isCPP(const std::string& path);

    /** Directory the running executable lives in, with trailing '/'. */
    std::string exeDir();

    /** Make path relative to one of the given base paths when possible. */
    std::string toRelative(const std::string& path, const std::vector<std::string>& basePaths);
}

#endif

