#include "path.h"

#include <algorithm>
#include <cstring>
#include <sys/stat.h>
#include <unistd.h>

namespace {
    const char * const cppExtensions[] = {".cpp", ".cxx", ".cc", ".c++", ".hpp", ".hxx", ".hh", ".tpp", ".txx", ".ipp", ".ixx"};
    const char * const acceptedExtensions[] = {".cpp", ".cxx", ".cc", ".c++", ".c", ".ipp", ".ixx", ".tpp", ".txx"};
}

std::string Path::toNativeSeparators(std::string path)
{
    std::replace(path.begin(), path.end(), '\\', '/');
    return path;
}

std::string Path::simplify(std::string path)
{
    path = toNativeSeparators(std::move(path));

    // remove leading "./" sequences
    while (path.compare(0, 2, "./") == 0)
        path.erase(0, 2);

    // collapse "//"
    std::string::size_type pos;
    while ((pos = path.find("//")) != std::string::npos)
        path.erase(pos, 1);

    // collapse "/./"
    while ((pos = path.find("/./")) != std::string::npos)
        path.erase(pos, 2);

    // resolve "dir/../"
    for (pos = path.find("/../"); pos != std::string::npos; pos = path.find("/../")) {
        const std::string::size_type prev = path.rfind('/', pos - 1);
        if (pos == 0)
            break;
        const std::string::size_type start = (prev == std::string::npos) ? 0 : prev + 1;
        if (path.compare(start, pos - start, "..") == 0)
            break;
        path.erase(start, pos + 4 - start);
        if (path.empty())
            break;
    }

    return path;
}

std::string Path::getExtension(const std::string& path, bool lowercase)
{
    const std::string::size_type dot = path.rfind('.');
    if (dot == std::string::npos)
        return "";
    const std::string::size_type slash = path.rfind('/');
    if (slash != std::string::npos && dot < slash)
        return "";
    std::string ext = path.substr(dot);
    if (lowercase)
        std::transform(ext.begin(), ext.end(), ext.begin(), [](unsigned char c) {
            return static_cast<char>(::tolower(c));
        });
    return ext;
}

std::string Path::getPath(const std::string& path)
{
    const std::string::size_type slash = path.rfind('/');
    if (slash == std::string::npos)
        return "";
    return path.substr(0, slash + 1);
}

std::string Path::getFilename(const std::string& path)
{
    const std::string::size_type slash = path.rfind('/');
    if (slash == std::string::npos)
        return path;
    return path.substr(slash + 1);
}

bool Path::isDirectory(const std::string& path)
{
    struct stat st;
    return ::stat(path.c_str(), &st) == 0 && S_ISDIR(st.st_mode);
}

bool Path::isFile(const std::string& path)
{
    struct stat st;
    return ::stat(path.c_str(), &st) == 0 && S_ISREG(st.st_mode);
}

bool Path::exists(const std::string& path)
{
    struct stat st;
    return ::stat(path.c_str(), &st) == 0;
}

long long Path::fileSize(const std::string& path)
{
    struct stat st;
    if (::stat(path.c_str(), &st) != 0)
        return 0;
    return static_cast<long long>(st.st_size);
}

bool Path::acceptFile(const std::string& path)
{
    const std::string ext = getExtension(path);
    for (const char * const e : acceptedExtensions) {
        if (ext == e)
            return true;
    }
    return false;
}

bool Path::isCPP(const std::string& path)
{
    const std::string ext = getExtension(path);
    for (const char * const e : cppExtensions) {
        if (ext == e)
            return true;
    }
    return false;
}

std::string Path::exeDir()
{
    char buf[4096];
    const ssize_t len = ::readlink("/proc/self/exe", buf, sizeof(buf) - 1);
    if (len <= 0)
        return "";
    buf[len] = '\0';
    return getPath(buf);
}

std::string Path::toRelative(const std::string& path, const std::vector<std::string>& basePaths)
{
    std::string result = path;
    for (const std::string& base : basePaths) {
        if (base.empty())
            continue;
        std::string prefix = base;
        if (prefix.back() != '/')
            prefix += '/';
        if (path.compare(0, prefix.size(), prefix) == 0) {
            const std::string candidate = path.substr(prefix.size());
            if (candidate.size() < result.size())
                result = candidate;
        }
    }
    return result;
}

