// Warning suppressions given with --suppress / --suppressions-list / inline comments.

#ifndef SUPPRESSIONS_H
#define SUPPRESSIONS_H

#include <list>
#include <string>

struct Suppression {
    std::string errorId;
    std::string fileName;
    int lineNumber = 0;
    std::string symbolName;
    bool matched = false;

    bool isMatch(const std::string& id, const std::string& file, int line) const;
};

class SuppressionList {
public:
    /** Parse a "[id]:[file]:[line]" specification. Returns an error text, empty on success. */
