#include "suppressions.h"

#include <cctype>
#include <cstdlib>
#include <fstream>

namespace {
    bool validIdChar(char c)
    {
        return std::isalnum(static_cast<unsigned char>(c)) || c == '_' || c == '-' || c == '*' || c == '?';
    }

    /** Shell style pattern match supporting '*' and '?'. */
    bool patternMatch(const std::string& pattern, const std::string& str)
    {
        size_t p = 0, s = 0, starP = std::string::npos, starS = 0;
        while (s < str.size()) {
            if (p < pattern.size() && (pattern[p] == '?' || pattern[p] == str[s])) {
                ++p;
                ++s;
            } else if (p < pattern.size() && pattern[p] == '*') {
                starP = p++;
                starS = s;
            } else if (starP != std::string::npos) {
                p = starP + 1;
                s = ++starS;
            } else {
                return false;
            }
        }
        while (p < pattern.size() && pattern[p] == '*')
            ++p;
        return p == pattern.size();
    }
}

bool Suppression::isMatch(const std::string& id, const std::string& file, int line) const
{
    if (!errorId.empty() && !patternMatch(errorId, id))
        return false;
    if (!fileName.empty() && !patternMatch(fileName, file))
        return false;
    if (lineNumber > 0 && lineNumber != line)
        return false;
    return true;
}

std::string SuppressionList::addSuppressionLine(const std::string& line)
{
    Suppression s;
    std::string text = line;

    // strip comment
    const std::string::size_type hash = text.find('#');
    if (hash != std::string::npos)
        text.erase(hash);
    while (!text.empty() && std::isspace(static_cast<unsigned char>(text.back())))
        text.pop_back();
    if (text.empty())
        return "";

    // "id:file:line" - the file name may itself contain ':' on some systems so
    // the line number is only taken when the last field is a number.
    std::string rest = text;
    const std::string::size_type colon = rest.find(':');
    if (colon == std::string::npos) {
        s.errorId = rest;
    } else {
        s.errorId = rest.substr(0, colon);
        rest = rest.substr(colon + 1);
        const std::string::size_type colon2 = rest.rfind(':');
        if (colon2 != std::string::npos) {
            const std::string lineStr = rest.substr(colon2 + 1);
            bool isNumber = !lineStr.empty();
            for (const char c : lineStr) {
                if (!std::isdigit(static_cast<unsigned char>(c)))
                    isNumber = false;
            }
            if (isNumber) {
                s.lineNumber = std::atoi(lineStr.c_str());
                rest = rest.substr(0, colon2);
            }
        }
        s.fileName = rest;
    }

    // an optional trailing "symbolName=x" is accepted after the id
    const std::string::size_type symPos = s.fileName.find("symbolName=");
    if (symPos == 0) {
        s.symbolName = s.fileName.substr(11);
        s.fileName.clear();
    }

    if (s.errorId.empty())
        return "Failed to add suppression. No id.";
    for (const char c : s.errorId) {
        if (!validIdChar(c))
            return "Failed to add suppression. Invalid id \"" + s.errorId + "\"";
    }

    mSuppressions.push_back(s);
    return "";
}

std::string SuppressionList::parseFile(const std::string& filename, std::string& errmsg)
{
    std::ifstream fin(filename);
    if (!fin.is_open()) {
        errmsg = "couldn't open the file: \"" + filename + "\".";
        return errmsg;
    }
    std::string line;
    while (std::getline(fin, line)) {
        if (!line.empty() && line.back() == '\r')
            line.pop_back();
        const std::string err = addSuppressionLine(line);
        if (!err.empty()) {
            errmsg = err;
            return errmsg;
        }
    }
    return "";
}

bool SuppressionList::isSuppressed(const std::string& id, const std::string& file, int line)
{
    bool suppressed = false;
    for (Suppression& s : mSuppressions) {
        if (s.isMatch(id, file, line)) {
            s.matched = true;
            suppressed = true;
        }
    }
    return suppressed;
}

