#ifndef ERRORLOGGER_H
#define ERRORLOGGER_H

#include <list>
#include <ostream>
#include <string>
#include <vector>

#include "settings.h"

struct ErrorLocation {
    std::string file;
    int line = 0;
    int column = 0;
    std::string info;
};

struct ErrorMessage {
    std::string id;
    Severity severity = Severity::error;
    std::string shortMessage;
    std::string verboseMessage;
    std::string file0;
    unsigned int cwe = 0;
    bool inconclusive = false;
    /** Chronological order; the last entry is where the problem is reported. */
    std::vector<ErrorLocation> locations;
    std::vector<std::string> symbolNames;

    ErrorMessage() = default;
    ErrorMessage(std::string id, Severity severity, std::string msg, unsigned int cwe = 0)
        : id(std::move(id)), severity(severity), shortMessage(std::move(msg)), cwe(cwe) {
        verboseMessage = shortMessage;
    }

    const ErrorLocation *primary() const {
        return locations.empty() ? nullptr : &locations.back();
    }
};

/** Escape a string for use as XML text or attribute value. */
std::string xmlEncode(const std::string& text);

