    void reportErr(const ErrorMessage& msg);

    /** Emit the header of the selected structured output format. */
    void reportHeader();
    /** Emit the footer of the selected structured output format. */
    void reportFooter();

    bool hasErrors() const {
        return mErrorCount > 0;
    }

private:
