            os << " info=\"" << xmlEncode(it->info) << '"';
        os << "/>\n";
    }
    for (const std::string& symbol : msg.symbolNames)
        os << "            <symbol>" << xmlEncode(symbol) << "</symbol>\n";
    os << "        </error>";
    return os.str();
}

namespace {
    /** Expand the {field} placeholders and the \\n \\t \\r escapes of a template. */
    std::string applyTemplate(const std::string& tmpl,
                              const ErrorMessage& msg,
                              const ErrorLocation *loc,
                              bool isLocationLine)
    {
        std::string result;
        for (std::string::size_type i = 0; i < tmpl.size(); ++i) {
            if (tmpl[i] == '\\' && i + 1 < tmpl.size()) {
                const char next = tmpl[i + 1];
                if (next == 'n') {
                    result += '\n';
                    ++i;
                    continue;
                }
                if (next == 't') {
                    result += '\t';
                    ++i;
                    continue;
                }
                if (next == 'r') {
                    result += '\r';
                    ++i;
                    continue;
                }
                result += tmpl[i];
                continue;
            }
            if (tmpl[i] != '{') {
                result += tmpl[i];
                continue;
            }
            const std::string::size_type end = tmpl.find('}', i);
            if (end == std::string::npos) {
                result += tmpl[i];
                continue;
            }
            const std::string field = tmpl.substr(i + 1, end - i - 1);
            std::string value;
            bool known = true;
            if (field == "file")
                value = loc ? loc->file : "nofile";
            else if (field == "line")
                value = std::to_string(loc ? loc->line : 0);
            else if (field == "column")
                value = std::to_string(loc ? loc->column : 0);
            else if (field == "severity")
                value = toString(msg.severity);
            else if (field == "message")
                value = msg.shortMessage;
            else if (field == "id")
                value = msg.id;
            else if (field == "cwe")
                value = std::to_string(msg.cwe);
            else if (field == "code")
                value = loc ? codeSnippet(loc->file, loc->line, loc->column) : std::string();
            else if (field == "info")
                value = loc ? loc->info : std::string();
            else if (field == "callstack") {
                if (isLocationLine) {
                    known = false;
                } else {
                    for (const ErrorLocation& l : msg.locations) {
                        if (!value.empty())
                            value += " -> ";
                        value += "[" + l.file + ":" + std::to_string(l.line) + "]";
                    }
                }
            } else if (field.compare(0, 14, "inconclusive:") == 0 || field.compare(0, 13, "inconclusive:") == 0)
                value = msg.inconclusive ? field.substr(13) : std::string();
            else
                known = false;

            if (!known)
                result += tmpl.substr(i, end - i + 1);
            else
                result += value;
            i = end;
        }
        return result;
    }
}

std::string ErrorLogger::formatText(const ErrorMessage& msg) const
{
    const ErrorLocation *primary = msg.primary();
    std::string result = applyTemplate(mSettings.templateFormat, msg, primary, false);

    if (!mSettings.templateLocation.empty() && msg.locations.size() > 1) {
        for (const ErrorLocation& loc : msg.locations) {
            result += '\n';
            result += applyTemplate(mSettings.templateLocation, msg, &loc, true);
        }
    }
    return result;
}

void ErrorLogger::reportErr(const ErrorMessage& msg)
{
    ++mErrorCount;
    switch (mSettings.outputFormat) {
    case OutputFormat::xml:
        mErr << formatXml(msg) << std::endl;
        break;
    case OutputFormat::sarif:
        mSarifMessages.push_back(msg);
        break;
    case OutputFormat::text:
        mErr << formatText(msg) << std::endl;
        break;
    }
}

