                std::string line;
                while (std::getline(std::cin, line)) {
                    if (!line.empty())
                        mPathNames.push_back(Path::toNativeSeparators(line));
                }
            } else {
                std::vector<std::string> lines;
                if (!loadLinesFromFile(filename, "couldn't open the file: \"" + filename + "\".", lines))
                    return Result::Fail;
                for (const std::string& line : lines)
                    mPathNames.push_back(Path::toNativeSeparators(line));
            }
        } else if (startsWith(arg, "--file-filter=")) {
            const std::string filter = arg.substr(14);
            if (filter == "-") {
                std::string line;
                while (std::getline(std::cin, line)) {
                    if (!line.empty())
                        mSettings.fileFilters.push_back(line);
                }
            } else {
                mSettings.fileFilters.push_back(filter);
            }
        } else if (startsWith(arg, "--suppress=")) {
            const std::string err = mSettings.suppressions.addSuppressionLine(arg.substr(11));
            if (!err.empty()) {
                printError(err);
                return Result::Fail;
            }
        } else if (startsWith(arg, "--suppressions-list=")) {
            const std::string filename = arg.substr(20);
            std::string errmsg;
            if (!mSettings.suppressions.parseFile(filename, errmsg).empty()) {
                printError(errmsg);
                return Result::Fail;
            }
        } else if (startsWith(arg, "--suppress-xml=")) {
            const std::string filename = arg.substr(15);
            if (!Path::isFile(filename)) {
                printError("failed to load suppressions XML '" + filename + "' (XML_ERROR_FILE_NOT_FOUND).");
                return Result::Fail;
            }
            std::string errmsg;
            if (!mSettings.suppressions.parseFile(filename, errmsg).empty()) {
                printError(errmsg);
                return Result::Fail;
            }
