            printError("Option --rule-file cannot be used as Cppcheck has not been built with rules support.");
            return Result::Fail;
        } else if (startsWith(arg, "--language=")) {
            const std::string lang = arg.substr(11);
            if (lang == "c")
                mSettings.enforcedLang = Language::c;
            else if (lang == "c++")
                mSettings.enforcedLang = Language::cpp;
            else {
                printError("unknown language '" + lang + "' enforced.");
                return Result::Fail;
