            if (!mSettings.userDefines.empty())
                mSettings.userDefines += ";";
            if (value.find('=') == std::string::npos)
                value += "=1";
            mSettings.userDefines += value;
            def = true;
        } else if (startsWith(arg, "-U")) {
            std::string value = arg.substr(2);
            if (value.empty()) {
                ++i;
                if (i >= argc) {
                    printError("argument to '-U' is missing.");
                    return Result::Fail;
                }
                value = argv[i];
            }
            mSettings.userUndefs.insert(value);
        } else if (startsWith(arg, "-I")) {
            std::string value = arg.substr(2);
            if (value.empty()) {
                ++i;
                if (i >= argc) {
                    printError("argument to '-I' is missing.");
                    return Result::Fail;
                }
                value = argv[i];
            }
            value = Path::toNativeSeparators(value);
            if (value.back() != '/')
                value += '/';
            mSettings.includePaths.push_back(value);
        } else if (startsWith(arg, "-i")) {
            std::string value = arg.substr(2);
            if (value.empty()) {
                ++i;
                if (i >= argc) {
                    printError("argument to '-i' is missing.");
                    return Result::Fail;
                }
                value = argv[i];
            }
            value = Path::toNativeSeparators(value);
            while (value.size() > 1 && value.back() == '/')
                value.pop_back();
            mSettings.ignoredPaths.push_back(value);
        } else if (startsWith(arg, "-j")) {
            std::string value = arg.substr(2);
            if (value.empty()) {
                ++i;
                if (i >= argc) {
                    printError("argument to '-j' is missing.");
                    return Result::Fail;
                }
                value = argv[i];
            }
            long long jobs = 0;
            const NumResult res = parseInt(value, jobs);
            if (res == NumResult::NotANumber) {
                printError("argument to '-j' is not valid - not an integer.");
                return Result::Fail;
            }
            if (res == NumResult::OutOfRange) {
                printError("argument to '-j' is not valid - out of range (limits).");
                return Result::Fail;
            }
            if (jobs < 1) {
                printError("argument for '-j' must be greater than 0.");
                return Result::Fail;
            }
            if (jobs > 1024) {
                printError("argument for '-j' is allowed to be 1024 at max.");
                return Result::Fail;
            }
            mSettings.jobs = static_cast<int>(jobs);
            mSettings.useSingleJob = (jobs == 1);
        } else if (startsWith(arg, "-l")) {
            std::string value = arg.substr(2);
            if (value.empty()) {
                ++i;
                if (i >= argc) {
                    printError("argument to '-l' is missing.");
                    return Result::Fail;
                }
                value = argv[i];
            }
            long long load = 0;
            const NumResult res = parseInt(value, load);
            if (res == NumResult::NotANumber) {
                printError("argument to '-l' is not valid - not an integer.");
                return Result::Fail;
            }
            if (res == NumResult::OutOfRange) {
                printError("argument to '-l' is not valid - out of range (limits).");
                return Result::Fail;
            }
            mSettings.loadAverage = static_cast<int>(load);
        } else {
            printError("unrecognized command line option: \"" + arg + "\".");
            return Result::Fail;
        }
    }

    if (mSettings.severities.empty())
        mSettings.severities.insert(Severity::error);
    else
        mSettings.severities.insert(Severity::error);

    if (mSettings.templateFormat.empty() && !mOutputFormatRequested && !mXmlRequested) {
        mSettings.templateFormat = "{file}:{line}:{column}: {severity}:{inconclusive: inconclusive:} {message} [{id}]\\n{code}";
        if (mSettings.templateLocation.empty())
            mSettings.templateLocation = "{file}:{line}:{column}: note: {info}\\n{code}";
    }

    if (mXmlRequested && mOutputFormatRequested) {
        printError("'--output-format' and '--xml...' may not be used in conjunction.");
        return Result::Fail;
    }

    if (maxconfigs && mSettings.force)
        mSettings.maxConfigs = INT_MAX;

    if (!mSettings.projectFile.empty() && !mPathNames.empty()) {
        printError("--project cannot be used in conjunction with source files.");
        return Result::Fail;
    }

    if (!mSettings.projectConfiguration.empty() && mSettings.projectFile.empty()) {
        printError("--project-configuration has no effect - no Visual Studio project provided.");
        return Result::Fail;
    }

    if (mPathNames.empty() && mSettings.projectFile.empty()) {
        printError("no C or C++ source files found.");
        return Result::Fail;
    }

    (void)def;
    return Result::Success;
}

