#include "cmdlineparser.h"

#include <algorithm>
#include <cctype>
#include <cerrno>
#include <climits>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <iostream>
#include <sstream>

#include "path.h"
#include "staticdata.h"
#include "version.h"

namespace {
    const char * const stdValuesC[] = {"c89", "c99", "c11", "c17", "c18", "c23"};
    const char * const stdValuesCpp[] = {"c++03", "c++11", "c++14", "c++17", "c++20", "c++23", "c++26"};

    bool startsWith(const std::string& str, const char *prefix)
    {
        return str.compare(0, std::strlen(prefix), prefix) == 0;
    }

    enum class NumResult { Ok, NotANumber, OutOfRange };

    NumResult parseInt(const std::string& text, long long& result)
    {
        if (text.empty())
            return NumResult::NotANumber;
        errno = 0;
        char *end = nullptr;
        const long long value = std::strtoll(text.c_str(), &end, 10);
        if (end == text.c_str() || *end != '\0')
            return NumResult::NotANumber;
        if (errno == ERANGE || value > INT_MAX || value < INT_MIN)
            return NumResult::OutOfRange;
        result = value;
        return NumResult::Ok;
    }
}

void CmdLineParser::printError(const std::string& message)
{
    printMessage("error: " + message);
}

void CmdLineParser::printMessage(const std::string& message)
{
    std::cout << "cppcheck: " << message << std::endl;
}

bool CmdLineParser::handleInformationalOption(const std::string& arg) const
{
    if (arg == "--version") {
        std::cout << "Cppcheck " CPPCHECK_VERSION_STRING << std::endl;
        return true;
    }
    if (arg == "--help" || arg == "-h") {
        std::cout << StaticData::helpText;
        std::cout.flush();
        return true;
    }
    if (arg == "--errorlist") {
        std::cout << StaticData::errorListXml;
        std::cout.flush();
        return true;
    }
    if (arg == "--doc") {
        std::cout << StaticData::docText;
        std::cout.flush();
        return true;
    }
    return false;
}

bool CmdLineParser::parseSeverityList(const std::string& value, bool enable)
{
    const char * const optionName = enable ? "--enable" : "--disable";
    if (value.empty()) {
        printError(std::string(optionName) + " parameter is empty");
        return false;
    }

    std::string::size_type pos = 0;
    while (pos <= value.size()) {
        const std::string::size_type comma = value.find(',', pos);
        const std::string name = value.substr(pos, comma == std::string::npos ? std::string::npos : comma - pos);
        pos = (comma == std::string::npos) ? value.size() + 1 : comma + 1;

        std::vector<Severity> severities;
        bool unusedFunction = false;
        bool missingInclude = false;

        if (name == "all") {
            severities = {Severity::warning, Severity::style, Severity::performance, Severity::portability, Severity::information};
            unusedFunction = missingInclude = true;
        } else if (name == "style") {
            severities = {Severity::style, Severity::warning, Severity::performance, Severity::portability};
        } else if (name == "warning") {
            severities = {Severity::warning};
        } else if (name == "performance") {
            severities = {Severity::performance};
        } else if (name == "portability") {
            severities = {Severity::portability};
        } else if (name == "information") {
            severities = {Severity::information};
            missingInclude = true;
        } else if (name == "unusedFunction") {
            unusedFunction = true;
        } else if (name == "missingInclude") {
            missingInclude = true;
        } else {
            printError(std::string(optionName) + " parameter with the unknown name '" + name + "'");
            return false;
        }

        for (const Severity severity : severities) {
            if (enable)
                mSettings.severities.insert(severity);
            else
                mSettings.severities.erase(severity);
        }
        if (unusedFunction)
            mSettings.checks.unusedFunction = enable;
        if (missingInclude)
            mSettings.checks.missingInclude = enable;
    }
    return true;
}

bool CmdLineParser::loadLinesFromFile(const std::string& filename, const std::string& errorText, std::vector<std::string>& lines) const
{
    std::ifstream fin(filename);
    if (!fin.is_open()) {
        printError(errorText);
        return false;
    }
    std::string line;
    while (std::getline(fin, line)) {
        if (!line.empty() && line.back() == '\r')
            line.pop_back();
        if (!line.empty())
            lines.push_back(line);
    }
    return true;
}

CmdLineParser::Result CmdLineParser::parseFromArgs(int argc, const char * const argv[])
{
    // The informational options are handled before any validation so that they
    // work even in combination with a bad command line.
    for (int i = 1; i < argc; ++i) {
        if (handleInformationalOption(argv[i]))
            return Result::Exit;
    }

    bool def = false;
    bool maxconfigs = false;

    for (int i = 1; i < argc; ++i) {
        const std::string arg = argv[i];

        if (arg.empty() || arg[0] != '-') {
            mPathNames.push_back(Path::toNativeSeparators(arg));
            continue;
        }

        if (arg == "--check-config") {
            mSettings.checkConfig = true;
        } else if (arg == "--check-library") {
            mSettings.checkLibrary = true;
        } else if (arg == "--check-headers") {
            mSettings.checkHeaders = true;
        } else if (arg == "--no-check-headers") {
            mSettings.checkHeaders = false;
        } else if (arg == "--check-unused-templates") {
            mSettings.checkUnusedTemplates = true;
        } else if (arg == "--no-check-unused-templates") {
            mSettings.checkUnusedTemplates = false;
        } else if (arg == "--clang") {
            mSettings.clang = true;
        } else if (startsWith(arg, "--clang=")) {
            mSettings.clang = true;
            mSettings.clangExecutable = arg.substr(8);
        } else if (arg == "--debug" || arg == "--debug-normal") {
            mSettings.debugNormal = true;
        } else if (arg == "--debug-simplified") {
            mSettings.debugSimplified = true;
        } else if (arg == "--debug-warnings") {
            mSettings.debugwarnings = true;
        } else if (arg == "--debug-template") {
            mSettings.debugtemplate = true;
        } else if (arg == "--debug-symdb") {
            mSettings.debugSymdb = true;
        } else if (arg == "--debug-valueflow") {
            mSettings.debugValueFlow = true;
        } else if (arg == "--debug-ast") {
            mSettings.debugAst = true;
        } else if (arg == "--debug-clang-output") {
            mSettings.debugClangOutput = true;
        } else if (arg == "--debug-lookup") {
            mSettings.debugLookup.emplace_back("all");
        } else if (startsWith(arg, "--debug-lookup=")) {
            const std::string what = arg.substr(15);
            if (what != "all" && what != "config" && what != "library" && what != "platform" && what != "addon") {
                printError("unknown lookup '" + what + "'");
                return Result::Fail;
            }
            mSettings.debugLookup.push_back(what);
        } else if (arg == "--dump") {
            mSettings.dump = true;
        } else if (arg == "-E") {
            mSettings.preprocessOnly = true;
        } else if (arg == "--emit-duplicates") {
            mSettings.emitDuplicates = true;
        } else if (arg == "--exception-handling") {
            mSettings.exceptionHandling = true;
        } else if (startsWith(arg, "--exception-handling=")) {
            const std::string dest = arg.substr(21);
            if (dest != "stderr" && dest != "stdout") {
                printError("invalid '--exception-handling' argument");
                return Result::Fail;
            }
            mSettings.exceptionHandling = true;
        } else if (arg == "-f" || arg == "--force") {
            mSettings.force = true;
        } else if (arg == "--fsigned-char") {
            mSettings.platform.defaultSignedChar = true;
        } else if (arg == "--funsigned-char") {
            mSettings.platform.defaultSignedChar = false;
        } else if (arg == "--inconclusive") {
            mSettings.inconclusive = true;
        } else if (arg == "--inline-suppr") {
            mSettings.inlineSuppressions = true;
        } else if (arg == "-q" || arg == "--quiet") {
            mSettings.quiet = true;
        } else if (arg == "-v" || arg == "--verbose") {
            mSettings.verbose = true;
        } else if (arg == "--report-progress") {
            mSettings.reportProgress = true;
        } else if (startsWith(arg, "--report-progress=")) {
            long long value = 0;
            if (parseInt(arg.substr(18), value) != NumResult::Ok) {
                printError("argument to '--report-progress=' is not valid - not an integer.");
                return Result::Fail;
            }
            mSettings.reportProgress = true;
            mSettings.reportProgressInterval = static_cast<int>(value);
        } else if (arg == "--safety") {
            mSettings.safety = true;
        } else if (arg == "--xml") {
            mXmlRequested = true;
            mSettings.outputFormat = OutputFormat::xml;
        } else if (startsWith(arg, "--xml-version=")) {
            long long value = 0;
            const NumResult res = parseInt(arg.substr(14), value);
            if (res != NumResult::Ok) {
                printError("argument to '--xml-version=' is not valid - not an integer.");
                return Result::Fail;
            }
            if (value != 2 && value != 3) {
                printError("'--xml-version' can only be 2 or 3.");
                return Result::Fail;
            }
            mXmlRequested = true;
            mSettings.xmlVersion = static_cast<int>(value);
            mSettings.outputFormat = OutputFormat::xml;
        } else if (startsWith(arg, "--output-format=")) {
            const std::string format = arg.substr(16);
            if (format == "text") {
                mSettings.outputFormat = OutputFormat::text;
            } else if (format == "sarif") {
                mSettings.outputFormat = OutputFormat::sarif;
            } else if (format == "xml" || format == "xmlv2") {
                mSettings.outputFormat = OutputFormat::xml;
                mSettings.xmlVersion = 2;
            } else if (format == "xmlv3") {
                mSettings.outputFormat = OutputFormat::xml;
                mSettings.xmlVersion = 3;
            } else {
                printError("argument to '--output-format=' must be 'text', 'sarif', 'xml' (deprecated), 'xmlv2' or 'xmlv3'.");
                return Result::Fail;
            }
            mOutputFormatRequested = true;
        } else if (startsWith(arg, "--output-file=")) {
            mSettings.outputFile = arg.substr(14);
        } else if (startsWith(arg, "--enable=")) {
            if (!parseSeverityList(arg.substr(9), true))
                return Result::Fail;
        } else if (startsWith(arg, "--disable=")) {
            if (!parseSeverityList(arg.substr(10), false))
                return Result::Fail;
        } else if (startsWith(arg, "--error-exitcode=")) {
            long long value = 0;
            const NumResult res = parseInt(arg.substr(17), value);
            if (res == NumResult::NotANumber) {
                printError("argument to '--error-exitcode=' is not valid - not an integer.");
                return Result::Fail;
            }
            if (res == NumResult::OutOfRange) {
                printError("argument to '--error-exitcode=' is not valid - out of range (limits).");
                return Result::Fail;
            }
            mSettings.exitCode = static_cast<int>(value);
        } else if (startsWith(arg, "--max-configs=")) {
            long long value = 0;
            const NumResult res = parseInt(arg.substr(14), value);
            if (res == NumResult::NotANumber) {
                printError("argument to '--max-configs=' is not valid - not an integer.");
                return Result::Fail;
            }
            if (res == NumResult::OutOfRange) {
                printError("argument to '--max-configs=' is not valid - out of range (limits).");
                return Result::Fail;
            }
            if (value < 1) {
                printError("argument to '--max-configs=' must be greater than 0.");
                return Result::Fail;
            }
            mSettings.maxConfigs = static_cast<int>(value);
            mSettings.force = false;
            maxconfigs = true;
        } else if (startsWith(arg, "--max-ctu-depth=")) {
            long long value = 0;
            const NumResult res = parseInt(arg.substr(16), value);
            if (res == NumResult::NotANumber) {
                printError("argument to '--max-ctu-depth=' is not valid - not an integer.");
                return Result::Fail;
            }
            if (res == NumResult::OutOfRange) {
                printError("argument to '--max-ctu-depth=' is not valid - out of range (limits).");
                return Result::Fail;
            }
            mSettings.maxCtuDepth = static_cast<int>(value);
        } else if (startsWith(arg, "--max-template-recursion=")) {
            long long value = 0;
            if (parseInt(arg.substr(25), value) != NumResult::Ok) {
                printError("argument to '--max-template-recursion=' is not valid - not an integer.");
                return Result::Fail;
            }
            mSettings.maxTemplateRecursion = static_cast<int>(value);
        } else if (startsWith(arg, "--performance-valueflow-max-time=") ||
                   startsWith(arg, "--performance-valueflow-max-if-count=") ||
                   startsWith(arg, "--valueflow-max-iterations=")) {
            const std::string::size_type eq = arg.find('=');
            long long value = 0;
            if (parseInt(arg.substr(eq + 1), value) != NumResult::Ok) {
                printError("argument to '" + arg.substr(0, eq + 1) + "' is not valid - not an integer.");
                return Result::Fail;
            }
        } else if (startsWith(arg, "--check-level=")) {
            const std::string level = arg.substr(14);
            if (level == "reduced")
                mSettings.checkLevel = CheckLevel::reduced;
            else if (level == "normal")
                mSettings.checkLevel = CheckLevel::normal;
            else if (level == "exhaustive")
                mSettings.checkLevel = CheckLevel::exhaustive;
            else {
                printError("unknown '--check-level' value '" + level + "'.");
                return Result::Fail;
            }
        } else if (startsWith(arg, "--std=")) {
            const std::string value = arg.substr(6);
            bool found = false;
            for (const char * const s : stdValuesC) {
                if (value == s) {
                    found = true;
                    if (value == "c89")
                        mSettings.standards.c = Standards::C89;
                    else if (value == "c99")
                        mSettings.standards.c = Standards::C99;
                    else if (value == "c11")
                        mSettings.standards.c = Standards::C11;
                    else if (value == "c23")
                        mSettings.standards.c = Standards::C23;
                    else
                        mSettings.standards.c = Standards::C17;
                }
            }
            for (const char * const s : stdValuesCpp) {
                if (value == s) {
                    found = true;
                    if (value == "c++03")
                        mSettings.standards.cpp = Standards::CPP03;
                    else if (value == "c++11")
                        mSettings.standards.cpp = Standards::CPP11;
                    else if (value == "c++14")
                        mSettings.standards.cpp = Standards::CPP14;
                    else if (value == "c++17")
                        mSettings.standards.cpp = Standards::CPP17;
                    else if (value == "c++20")
                        mSettings.standards.cpp = Standards::CPP20;
                    else if (value == "c++23")
                        mSettings.standards.cpp = Standards::CPP23;
                    else
                        mSettings.standards.cpp = Standards::CPP26;
                }
            }
            if (!found) {
                printError("unknown --std value '" + value + "'");
                return Result::Fail;
            }
        } else if (startsWith(arg, "--platform=")) {
            const std::string value = arg.substr(11);
            if (value.empty()) {
                printError("empty platform specified.");
                return Result::Fail;
            }
            if (!mSettings.platform.setBuiltin(value)) {
                if (!Path::isFile(value)) {
                    printError("unrecognized platform: '" + value + "'.");
                    return Result::Fail;
                }
                mSettings.platform.name = value;
            }
        } else if (startsWith(arg, "--library=")) {
            const std::string value = arg.substr(10);
            if (value.empty()) {
                printError("empty library specified.");
                return Result::Fail;
            }
            std::string::size_type pos = 0;
            while (pos < value.size()) {
                const std::string::size_type comma = value.find(',', pos);
                const std::string lib = value.substr(pos, comma == std::string::npos ? std::string::npos : comma - pos);
                if (lib.empty()) {
                    printError("empty library specified.");
                    return Result::Fail;
                }
                mSettings.libraries.push_back(lib);
                if (comma == std::string::npos)
                    break;
                pos = comma + 1;
            }
        } else if (startsWith(arg, "--addon=")) {
            mSettings.addons.push_back(arg.substr(8));
        } else if (startsWith(arg, "--addon-python=")) {
            mSettings.addonPython = arg.substr(15);
        } else if (startsWith(arg, "--include=")) {
            mSettings.userIncludes.push_back(Path::toNativeSeparators(arg.substr(10)));
        } else if (startsWith(arg, "--includes-file=")) {
            std::vector<std::string> lines;
            if (!loadLinesFromFile(arg.substr(16), "unable to open includes file at '" + arg.substr(16) + "'", lines))
                return Result::Fail;
            for (std::string& line : lines) {
                line = Path::toNativeSeparators(line);
                if (line.back() != '/')
                    line += '/';
                mSettings.includePaths.push_back(line);
            }
        } else if (startsWith(arg, "--config-exclude=")) {
            mSettings.configExcludePaths.push_back(Path::toNativeSeparators(arg.substr(17)));
        } else if (startsWith(arg, "--config-excludes-file=")) {
            std::vector<std::string> lines;
            if (!loadLinesFromFile(arg.substr(23), "unable to open config excludes file at '" + arg.substr(23) + "'", lines))
                return Result::Fail;
            for (const std::string& line : lines)
                mSettings.configExcludePaths.push_back(Path::toNativeSeparators(line));
        } else if (startsWith(arg, "--file-list=")) {
            const std::string filename = arg.substr(12);
            if (filename == "-") {
                std::string line;
                while (std::getline(std::cin, line)) {
                    if (!line.empty())
                        mPathNames.push_back(Path::toNativeSeparators(line));
                }
            } else {
                std::vector<std::string> lines;
                if (!loadLinesFromFile(filename, "couldn't open the file: \"" + filename + "\".", lines))
                    return Result::Fail;
                for (const std::string& line : lines)
                    mPathNames.push_back(Path::toNativeSeparators(line));
            }
        } else if (startsWith(arg, "--file-filter=")) {
            const std::string filter = arg.substr(14);
            if (filter == "-") {
                std::string line;
                while (std::getline(std::cin, line)) {
                    if (!line.empty())
                        mSettings.fileFilters.push_back(line);
                }
            } else {
                mSettings.fileFilters.push_back(filter);
            }
        } else if (startsWith(arg, "--suppress=")) {
            const std::string err = mSettings.suppressions.addSuppressionLine(arg.substr(11));
            if (!err.empty()) {
                printError(err);
                return Result::Fail;
            }
        } else if (startsWith(arg, "--suppressions-list=")) {
            const std::string filename = arg.substr(20);
            std::string errmsg;
            if (!mSettings.suppressions.parseFile(filename, errmsg).empty()) {
                printError(errmsg);
                return Result::Fail;
            }
        } else if (startsWith(arg, "--suppress-xml=")) {
            const std::string filename = arg.substr(15);
            if (!Path::isFile(filename)) {
                printError("failed to load suppressions XML '" + filename + "' (XML_ERROR_FILE_NOT_FOUND).");
                return Result::Fail;
            }
            std::string errmsg;
            if (!mSettings.suppressions.parseFile(filename, errmsg).empty()) {
                printError(errmsg);
                return Result::Fail;
            }
        } else if (startsWith(arg, "--exitcode-suppressions=")) {
            const std::string filename = arg.substr(24);
            std::string errmsg;
            if (!mSettings.exitcodeSuppressions.parseFile(filename, errmsg).empty()) {
                printError(errmsg);
                return Result::Fail;
            }
        } else if (startsWith(arg, "--template=")) {
            const std::string value = arg.substr(11);
            if (value == "gcc") {
                mSettings.templateFormat = "{file}:{line}:{column}: warning: {message} [{id}]\\n{code}";
                mSettings.templateLocation = "{file}:{line}:{column}: note: {info}\\n{code}";
            } else if (value == "cppcheck1") {
                mSettings.templateFormat = "{callstack}: ({severity}{inconclusive:, inconclusive}) {message}";
                mSettings.templateLocation.clear();
            } else if (value == "vs") {
                mSettings.templateFormat = "{file}({line}): {severity}: {message}";
                mSettings.templateLocation.clear();
            } else if (value == "edit") {
                mSettings.templateFormat = "{file} +{line}: {severity}: {message}";
                mSettings.templateLocation.clear();
            } else if (value == "daca2") {
                mSettings.templateFormat = "{file}:{line}:{column}: {severity}:{inconclusive: inconclusive:} {message} [{id}]";
                mSettings.templateLocation = "{file}:{line}:{column}: note: {info}";
            } else if (value == "selfcheck") {
                mSettings.templateFormat = "{file}:{line}:{column}: {severity}:{inconclusive: inconclusive:} {message} [{id}]\\n{code}";
                mSettings.templateLocation = "{file}:{line}:{column}: note: {info}\\n{code}";
            } else if (value == "simple") {
                mSettings.templateFormat = "{file}:{line}:{column}: {severity}:{inconclusive: inconclusive:} {message} [{id}]";
                mSettings.templateLocation.clear();
            } else {
                mSettings.templateFormat = value;
            }
        } else if (startsWith(arg, "--template-location=")) {
            mSettings.templateLocation = arg.substr(20);
        } else if (startsWith(arg, "--cppcheck-build-dir=")) {
            const std::string dir = arg.substr(21);
            if (dir.empty()) {
                printError("no path has been specified for --cppcheck-build-dir");
                return Result::Fail;
            }
            if (!Path::isDirectory(dir)) {
                printError("Directory '" + dir + "' specified by --cppcheck-build-dir argument has to be existent.");
                return Result::Fail;
            }
            mSettings.buildDir = dir;
        } else if (arg == "--no-cppcheck-build-dir") {
            mSettings.buildDir.clear();
        } else if (startsWith(arg, "--plist-output=")) {
            std::string dir = arg.substr(15);
            if (dir.empty())
                dir = ".";
            if (!Path::isDirectory(dir)) {
                printError("plist folder does not exist: '" + arg.substr(15) + "'.");
                return Result::Fail;
            }
            mSettings.plistOutput = dir;
        } else if (startsWith(arg, "--checkers-report=")) {
            mSettings.checkersReportFilename = arg.substr(18);
        } else if (startsWith(arg, "--project=")) {
            const std::string filename = arg.substr(10);
            if (!Path::isFile(filename)) {
                printError("failed to open project '" + filename + "'. The file does not exist.");
                return Result::Fail;
            }
            mSettings.projectFile = filename;
        } else if (startsWith(arg, "--project-configuration=")) {
            mSettings.projectConfiguration = arg.substr(24);
        } else if (startsWith(arg, "--report-type=")) {
            const std::string type = arg.substr(14);
            if (type == "normal")
                mSettings.reportType = ReportType::normal;
            else if (type == "autosar")
                mSettings.reportType = ReportType::autosar;
            else if (type == "cert-c-2016")
                mSettings.reportType = ReportType::certC;
            else if (type == "cert-cpp-2016")
                mSettings.reportType = ReportType::certCpp;
            else if (type == "misra-c-2012")
                mSettings.reportType = ReportType::misraC2012;
            else if (type == "misra-c-2023")
                mSettings.reportType = ReportType::misraC2023;
            else if (type == "misra-c-2025")
                mSettings.reportType = ReportType::misraC2025;
            else if (type == "misra-cpp-2008")
                mSettings.reportType = ReportType::misraCpp2008;
            else if (type == "misra-cpp-2023")
                mSettings.reportType = ReportType::misraCpp2023;
            else {
                printError("Unknown report type '" + type + "'");
                return Result::Fail;
            }
        } else if (startsWith(arg, "--showtime=")) {
            const std::string mode = arg.substr(11);
            if (mode.empty()) {
                printError("no mode provided for --showtime");
                return Result::Fail;
            }
            if (mode == "file")
                mSettings.showtime = ShowTime::file;
            else if (mode == "file-total")
                mSettings.showtime = ShowTime::fileTotal;
            else if (mode == "summary")
                mSettings.showtime = ShowTime::summary;
            else if (mode == "top5_file")
                mSettings.showtime = ShowTime::top5File;
            else if (mode == "top5_summary")
                mSettings.showtime = ShowTime::top5Summary;
            else if (mode == "none")
                mSettings.showtime = ShowTime::none;
            else {
                printError("unrecognized --showtime mode: '" + mode + "'. Supported modes: file, file-total, summary, top5_file, top5_summary.");
                return Result::Fail;
            }
        } else if (startsWith(arg, "--rule=")) {
            printError("Option --rule cannot be used as Cppcheck has not been built with rules support.");
            return Result::Fail;
        } else if (startsWith(arg, "--rule-file=")) {
            printError("Option --rule-file cannot be used as Cppcheck has not been built with rules support.");
            return Result::Fail;
        } else if (startsWith(arg, "--language=")) {
            const std::string lang = arg.substr(11);
            if (lang == "c")
                mSettings.enforcedLang = Language::c;
            else if (lang == "c++")
                mSettings.enforcedLang = Language::cpp;
            else {
                printError("unknown language '" + lang + "' enforced.");
                return Result::Fail;
            }
        } else if (arg == "-x") {
            ++i;
            if (i >= argc) {
                printError("no language given to '-x' option.");
                return Result::Fail;
            }
            const std::string lang = argv[i];
            if (lang == "c")
                mSettings.enforcedLang = Language::c;
            else if (lang == "c++")
                mSettings.enforcedLang = Language::cpp;
            else {
                printError("unknown language '" + lang + "' enforced.");
                return Result::Fail;
            }
        } else if (arg == "-rp" || arg == "--relative-paths") {
            mSettings.relativePaths = true;
        } else if (startsWith(arg, "-rp=") || startsWith(arg, "--relative-paths=")) {
            mSettings.relativePaths = true;
            const std::string value = arg.substr(arg[1] == 'r' ? 4 : 17);
            std::string::size_type pos = 0;
            while (pos < value.size()) {
                const std::string::size_type sep = value.find(';', pos);
                std::string path = value.substr(pos, sep == std::string::npos ? std::string::npos : sep - pos);
                if (!path.empty())
                    mSettings.basePaths.push_back(Path::toNativeSeparators(path));
                if (sep == std::string::npos)
                    break;
                pos = sep + 1;
            }
        } else if (startsWith(arg, "-D")) {
            std::string value = arg.substr(2);
            if (value.empty()) {
                ++i;
                if (i >= argc) {
                    printError("argument to '-D' is missing.");
                    return Result::Fail;
                }
                value = argv[i];
            }
            if (!mSettings.userDefines.empty())
                mSettings.userDefines += ";";
            if (value.find('=') == std::string::npos)
                value += "=1";
            mSettings.userDefines += value;
            def = true;
        } else if (startsWith(arg, "-U")) {
            std::string value = arg.substr(2);
            if (value.empty()) {
                ++i;
                if (i >= argc) {
                    printError("argument to '-U' is missing.");
                    return Result::Fail;
                }
                value = argv[i];
            }
            mSettings.userUndefs.insert(value);
        } else if (startsWith(arg, "-I")) {
            std::string value = arg.substr(2);
            if (value.empty()) {
                ++i;
                if (i >= argc) {
                    printError("argument to '-I' is missing.");
                    return Result::Fail;
                }
                value = argv[i];
            }
            value = Path::toNativeSeparators(value);
            if (value.back() != '/')
                value += '/';
            mSettings.includePaths.push_back(value);
        } else if (startsWith(arg, "-i")) {
            std::string value = arg.substr(2);
            if (value.empty()) {
                ++i;
                if (i >= argc) {
                    printError("argument to '-i' is missing.");
                    return Result::Fail;
                }
                value = argv[i];
            }
            value = Path::toNativeSeparators(value);
            while (value.size() > 1 && value.back() == '/')
                value.pop_back();
            mSettings.ignoredPaths.push_back(value);
        } else if (startsWith(arg, "-j")) {
            std::string value = arg.substr(2);
            if (value.empty()) {
                ++i;
                if (i >= argc) {
                    printError("argument to '-j' is missing.");
                    return Result::Fail;
                }
                value = argv[i];
            }
            long long jobs = 0;
            const NumResult res = parseInt(value, jobs);
            if (res == NumResult::NotANumber) {
                printError("argument to '-j' is not valid - not an integer.");
                return Result::Fail;
            }
            if (res == NumResult::OutOfRange) {
                printError("argument to '-j' is not valid - out of range (limits).");
                return Result::Fail;
            }
            if (jobs < 1) {
                printError("argument for '-j' must be greater than 0.");
                return Result::Fail;
            }
            if (jobs > 1024) {
