#include "library.h"

#include <fstream>
#include <sstream>

#include "xmlparser.h"

Library::Error Library::load(const std::string& path, std::string& xmlError, std::string& badRootName)
{
    std::ifstream fin(path, std::ios::binary);
    if (!fin.is_open())
        return Error::FileNotFound;

    std::ostringstream buffer;
    buffer << fin.rdbuf();

    XmlDocument doc;
    if (!doc.parse(buffer.str())) {
        xmlError = doc.errorText();
        return Error::BadXml;
    }

    const XmlNode *root = doc.root();
    if (!root)
        return Error::BadXml;

    if (root->name != "def") {
        badRootName = root->name;
        return Error::UnsupportedFormatNamed;
    }

    const std::string format = root->attribute("format");
    if (!format.empty() && format != "1" && format != "2")
        return Error::UnsupportedFormat;

    for (const XmlNode& node : root->children) {
        if (node.name == "function") {
            LibraryFunction func;
            func.name = node.attribute("name");
            if (func.name.empty())
                continue;
            for (const XmlNode& child : node.children) {
                if (child.name == "noreturn")
                    func.noreturn = (child.text != "false");
                else if (child.name == "leak-ignore")
                    func.leakIgnore = true;
            }
            // several names may be listed, separated by ','
            std::string::size_type pos = 0;
            const std::string names = func.name;
            while (pos < names.size()) {
                const std::string::size_type comma = names.find(',', pos);
                const std::string one = names.substr(pos, comma == std::string::npos ? std::string::npos : comma - pos);
                if (!one.empty()) {
                    LibraryFunction f = func;
                    f.name = one;
                    mFunctions[one] = f;
                }
                if (comma == std::string::npos)
                    break;
                pos = comma + 1;
            }
        } else if (node.name == "podtype") {
            const std::string names = node.attribute("name");
            std::string::size_type pos = 0;
            while (pos < names.size()) {
                const std::string::size_type comma = names.find(',', pos);
                const std::string one = names.substr(pos, comma == std::string::npos ? std::string::npos : comma - pos);
                if (!one.empty())
                    mPodTypes.insert(one);
                if (comma == std::string::npos)
                    break;
                pos = comma + 1;
            }
        } else if (node.name == "memory" || node.name == "resource") {
            for (const XmlNode& child : node.children) {
                if (child.name == "alloc") {
                    LibraryFunction f;
                    f.name = child.text;
                    f.allocFor = node.name;
                    if (!f.name.empty())
                        mFunctions[f.name] = f;
                } else if (child.name == "dealloc") {
                    LibraryFunction f;
                    f.name = child.text;
                    f.deallocFor = node.name;
                    if (!f.name.empty())
                        mFunctions[f.name] = f;
                }
            }
        }
    }

    return Error::Ok;
}

const LibraryFunction *Library::getFunction(const std::string& name) const
{
    const auto it = mFunctions.find(name);
    return (it == mFunctions.end()) ? nullptr : &it->second;
}

bool Library::isNoReturn(const std::string& name) const
{
    const LibraryFunction *func = getFunction(name);
    return func && func->noreturn;
}

