#include "xmlparser.h"

#include <cctype>
#include <sstream>

namespace {
    struct Cursor {
        const std::string& data;
        std::string::size_type pos = 0;
        int line = 1;

        explicit Cursor(const std::string& d) : data(d) {}

        bool eof() const {
            return pos >= data.size();
        }
        char peek() const {
            return pos < data.size() ? data[pos] : '\0';
        }
        char get() {
            const char c = data[pos++];
            if (c == '\n')
                ++line;
            return c;
        }
        bool startsWith(const char *text) const {
            return data.compare(pos, std::string::size_type(std::string(text).size()), text) == 0;
        }
        void skipSpace() {
            while (!eof() && std::isspace(static_cast<unsigned char>(peek())))
                get();
        }
    };

    std::string decodeEntities(const std::string& text)
    {
        std::string result;
        for (std::string::size_type i = 0; i < text.size(); ++i) {
            if (text[i] != '&') {
                result += text[i];
                continue;
            }
            const std::string::size_type semi = text.find(';', i);
            if (semi == std::string::npos || semi - i > 10) {
                result += text[i];
                continue;
            }
            const std::string entity = text.substr(i + 1, semi - i - 1);
            if (entity == "lt")
                result += '<';
            else if (entity == "gt")
                result += '>';
            else if (entity == "amp")
                result += '&';
            else if (entity == "quot")
                result += '"';
            else if (entity == "apos")
                result += '\'';
            else if (!entity.empty() && entity[0] == '#')
                result += static_cast<char>(std::strtol(entity.c_str() + 1, nullptr, entity.size() > 1 && entity[1] == 'x' ? 16 : 10));
            else {
                result += text[i];
                continue;
            }
            i = semi;
        }
        return result;
    }

    bool nameChar(char c)
    {
        return std::isalnum(static_cast<unsigned char>(c)) || c == '_' || c == '-' || c == ':' || c == '.';
    }

    /** Skip <?...?>, <!--...-->, <!DOCTYPE...>. Returns false on malformed input. */
    bool skipProlog(Cursor& cur)
    {
        for (;;) {
            cur.skipSpace();
            if (cur.eof())
                return true;
            if (cur.peek() != '<')
                return false;
            if (cur.startsWith("<?")) {
                const std::string::size_type end = cur.data.find("?>", cur.pos);
                if (end == std::string::npos)
                    return false;
                while (cur.pos < end + 2)
                    cur.get();
            } else if (cur.startsWith("<!--")) {
                const std::string::size_type end = cur.data.find("-->", cur.pos);
                if (end == std::string::npos)
                    return false;
                while (cur.pos < end + 3)
                    cur.get();
            } else if (cur.startsWith("<!")) {
                const std::string::size_type end = cur.data.find('>', cur.pos);
                if (end == std::string::npos)
                    return false;
                while (cur.pos <= end)
                    cur.get();
            } else {
                return true;
            }
        }
    }

    bool parseElement(Cursor& cur, XmlNode& node);

    /** Parse the children and text of an element until its closing tag. */
    bool parseContent(Cursor& cur, XmlNode& node)
    {
        std::string text;
        for (;;) {
            if (cur.eof())
                return false;
            if (cur.peek() == '<') {
                if (cur.startsWith("</")) {
                    while (!cur.eof() && cur.peek() != '>')
                        cur.get();
                    if (cur.eof())
                        return false;
                    cur.get();
                    node.text = decodeEntities(text);
                    // trim
                    while (!node.text.empty() && std::isspace(static_cast<unsigned char>(node.text.front())))
                        node.text.erase(0, 1);
                    while (!node.text.empty() && std::isspace(static_cast<unsigned char>(node.text.back())))
                        node.text.pop_back();
                    return true;
                }
                if (cur.startsWith("<!--")) {
                    const std::string::size_type end = cur.data.find("-->", cur.pos);
                    if (end == std::string::npos)
                        return false;
                    while (cur.pos < end + 3)
                        cur.get();
                    continue;
                }
                XmlNode child;
                if (!parseElement(cur, child))
                    return false;
                node.children.push_back(std::move(child));
                continue;
            }
            text += cur.get();
        }
    }

    bool parseElement(Cursor& cur, XmlNode& node)
    {
        if (cur.peek() != '<')
            return false;
        cur.get();
        while (!cur.eof() && nameChar(cur.peek()))
            node.name += cur.get();
        if (node.name.empty())
            return false;

        for (;;) {
            cur.skipSpace();
            if (cur.eof())
                return false;
            if (cur.peek() == '/') {
                cur.get();
                if (cur.eof() || cur.peek() != '>')
                    return false;
                cur.get();
                return true;
            }
            if (cur.peek() == '>') {
                cur.get();
                return parseContent(cur, node);
            }
            std::string key;
            while (!cur.eof() && nameChar(cur.peek()))
                key += cur.get();
            if (key.empty())
                return false;
            cur.skipSpace();
            if (cur.eof() || cur.peek() != '=')
                return false;
            cur.get();
            cur.skipSpace();
            if (cur.eof() || (cur.peek() != '"' && cur.peek() != '\''))
                return false;
            const char quote = cur.get();
            std::string value;
            while (!cur.eof() && cur.peek() != quote)
                value += cur.get();
            if (cur.eof())
                return false;
            cur.get();
            node.attributes[key] = decodeEntities(value);
        }
    }
}

bool XmlDocument::parse(const std::string& data)
{
    Cursor cur(data);
    if (!skipProlog(cur)) {
        std::ostringstream os;
        os << "Error=XML_ERROR_PARSING_DECLARATION ErrorID=6 (0x6) Line number=" << cur.line;
        mErrorText = os.str();
        return false;
    }
    cur.skipSpace();
    if (cur.eof() || cur.peek() != '<') {
        std::ostringstream os;
        os << "Error=XML_ERROR_PARSING_TEXT ErrorID=8 (0x8) Line number=" << cur.line;
        mErrorText = os.str();
        return false;
    }
    if (!parseElement(cur, mRoot)) {
        std::ostringstream os;
        os << "Error=XML_ERROR_PARSING_ELEMENT ErrorID=9 (0x9) Line number=" << cur.line;
        mErrorText = os.str();
        mRoot = XmlNode();
        return false;
    }
    return true;
}

