                if (!parseElement(cur, child))
                    return false;
                node.children.push_back(std::move(child));
                continue;
            }
            text += cur.get();
        }
    }

    bool parseElement(Cursor& cur, XmlNode& node)
    {
        if (cur.peek() != '<')
            return false;
        cur.get();
        while (!cur.eof() && nameChar(cur.peek()))
            node.name += cur.get();
        if (node.name.empty())
            return false;

        for (;;) {
            cur.skipSpace();
            if (cur.eof())
                return false;
            if (cur.peek() == '/') {
                cur.get();
                if (cur.eof() || cur.peek() != '>')
                    return false;
                cur.get();
                return true;
            }
            if (cur.peek() == '>') {
                cur.get();
                return parseContent(cur, node);
            }
            std::string key;
            while (!cur.eof() && nameChar(cur.peek()))
                key += cur.get();
            if (key.empty())
                return false;
            cur.skipSpace();
            if (cur.eof() || cur.peek() != '=')
                return false;
            cur.get();
            cur.skipSpace();
            if (cur.eof() || (cur.peek() != '"' && cur.peek() != '\''))
                return false;
            const char quote = cur.get();
            std::string value;
            while (!cur.eof() && cur.peek() != quote)
                value += cur.get();
            if (cur.eof())
                return false;
            cur.get();
            node.attributes[key] = decodeEntities(value);
        }
    }
}

bool XmlDocument::parse(const std::string& data)
{
    Cursor cur(data);
    if (!skipProlog(cur)) {
        std::ostringstream os;
        os << "Error=XML_ERROR_PARSING_DECLARATION ErrorID=6 (0x6) Line number=" << cur.line;
        mErrorText = os.str();
        return false;
    }
    cur.skipSpace();
    if (cur.eof() || cur.peek() != '<') {
        std::ostringstream os;
        os << "Error=XML_ERROR_PARSING_TEXT ErrorID=8 (0x8) Line number=" << cur.line;
        mErrorText = os.str();
        return false;
    }
    if (!parseElement(cur, mRoot)) {
        std::ostringstream os;
        os << "Error=XML_ERROR_PARSING_ELEMENT ErrorID=9 (0x9) Line number=" << cur.line;
        mErrorText = os.str();
        mRoot = XmlNode();
        return false;
    }
    return true;
}

