#include "filelister.h"

#include <algorithm>
#include <dirent.h>
#include <set>

#include "path.h"

namespace {
    bool wildcardMatch(const std::string& pattern, const std::string& str)
    {
        size_t p = 0, s = 0, starP = std::string::npos, starS = 0;
        while (s < str.size()) {
            if (p < pattern.size() && (pattern[p] == '?' || pattern[p] == str[s])) {
                ++p;
                ++s;
            } else if (p < pattern.size() && pattern[p] == '*') {
                starP = p++;
                starS = s;
            } else if (starP != std::string::npos) {
                p = starP + 1;
                s = ++starS;
            } else {
                return false;
            }
        }
        while (p < pattern.size() && pattern[p] == '*')
            ++p;
        return p == pattern.size();
    }

    /** A -i entry matches a file name, a directory name or a wildcard pattern. */
    bool isIgnored(const std::string& path, const std::vector<std::string>& ignored)
    {
        for (const std::string& pattern : ignored) {
            if (pattern.empty())
                continue;
            if (pattern.find_first_of("*?") != std::string::npos) {
                if (wildcardMatch(pattern, path) || wildcardMatch(pattern, Path::getFilename(path)))
                    return true;
                continue;
            }
            if (path == pattern)
                return true;
            // match a complete path component
            std::string::size_type pos = 0;
            while ((pos = path.find(pattern, pos)) != std::string::npos) {
                const bool startOk = (pos == 0) || (path[pos - 1] == '/');
                const std::string::size_type end = pos + pattern.size();
                const bool endOk = (end == path.size()) || (path[end] == '/');
                if (startOk && endOk)
                    return true;
                ++pos;
            }
        }
        return false;
    }

    bool matchesFilter(const std::string& path, const std::vector<std::string>& filters)
    {
        if (filters.empty())
            return true;
        for (const std::string& filter : filters) {
            if (wildcardMatch(filter, path) || wildcardMatch(filter, Path::getFilename(path)))
                return true;
        }
        return false;
    }

    void recurse(const std::string& dir, const std::vector<std::string>& ignored, std::vector<std::string>& found)
    {
        DIR *handle = ::opendir(dir.c_str());
        if (!handle)
            return;

        std::vector<std::string> entries;
        while (const dirent *entry = ::readdir(handle)) {
            const std::string name = entry->d_name;
            if (name == "." || name == "..")
                continue;
            entries.push_back(name);
        }
        ::closedir(handle);
        std::sort(entries.begin(), entries.end());

        for (const std::string& name : entries) {
            std::string full = dir;
            if (!full.empty() && full.back() != '/')
                full += '/';
            full += name;
            if (isIgnored(full, ignored))
                continue;
            if (Path::isDirectory(full))
                recurse(full, ignored, found);
            else if (Path::acceptFile(full))
                found.push_back(full);
        }
    }
}

std::vector<FileEntry> FileLister::collect(const std::vector<std::string>& paths,
                                           const std::vector<std::string>& ignored,
                                           const std::vector<std::string>& filters)
{
    std::vector<FileEntry> result;
    std::set<std::string> seen;

    for (const std::string& given : paths) {
        std::string path = Path::simplify(given);
        if (path.empty())
            continue;
        while (path.size() > 1 && path.back() == '/')
            path.pop_back();

        std::vector<std::string> found;
        if (Path::isDirectory(path))
            recurse(path, ignored, found);
        else if (Path::isFile(path) && !isIgnored(path, ignored))
            found.push_back(path);

        for (const std::string& file : found) {
            if (!matchesFilter(file, filters))
                continue;
            if (!seen.insert(file).second)
                continue;
            FileEntry entry;
            entry.path = file;
            entry.size = Path::fileSize(file);
            result.push_back(entry);
        }
    }

    return result;
}

