#include "cppcheckexecutor.h"

#include <fstream>
#include <iostream>
#include <sstream>

#include "cppcheck.h"
#include "errorlogger.h"
#include "filelister.h"
#include "path.h"
#include "version.h"

namespace {
    /** Candidate locations for a library configuration file, in lookup order. */
    std::vector<std::string> libraryCandidates(const std::string& name)
    {
        std::string filename = name;
        if (Path::getExtension(filename) != ".cfg")
            filename += ".cfg";

        std::vector<std::string> candidates;
        candidates.push_back(filename);
        const std::string exeDir = Path::exeDir();
        if (!exeDir.empty()) {
            candidates.push_back(exeDir + filename);
            candidates.push_back(exeDir + "cfg/" + filename);
        }
        candidates.push_back(std::string(CPPCHECK_FILESDIR) + "/cfg/" + filename);
        return candidates;
    }
}

void CppCheckExecutor::lookupConfigFile() const
{
    const bool trace = mSettings.debugLookupEnabled("config");
    const std::vector<std::string> candidates = {
        std::string(CPPCHECK_FILESDIR) + "/cppcheck.cfg",
        Path::exeDir() + "cppcheck.cfg"
    };
    for (const std::string& candidate : candidates) {
        if (trace)
            std::cout << "looking for '" << candidate << "'" << std::endl;
        if (Path::isFile(candidate))
            return;
    }
    if (trace)
        std::cout << "no configuration found" << std::endl;
}

bool CppCheckExecutor::loadLibraries()
{
    const bool trace = mSettings.debugLookupEnabled("library");

    std::vector<std::string> names;
    names.emplace_back("std.cfg");
    for (const std::string& lib : mSettings.libraries)
        names.push_back(lib);

    for (const std::string& name : names) {
        if (trace)
            std::cout << "looking for library '" << name << "'" << std::endl;

        bool loaded = false;
        for (const std::string& candidate : libraryCandidates(name)) {
            if (trace && candidate != name)
                std::cout << "looking for library '" << candidate << "'" << std::endl;
            std::string xmlError;
            std::string badRoot;
            const Library::Error err = mLibrary.load(candidate, xmlError, badRoot);
            if (err == Library::Error::FileNotFound)
                continue;

            if (err == Library::Error::BadXml) {
                std::cout << xmlError << std::endl;
                std::cout << "cppcheck: Failed to load library configuration file '" << name << "'. Bad XML" << std::endl;
                return false;
            }
            if (err == Library::Error::UnsupportedFormat) {
                std::cout << "cppcheck: Failed to load library configuration file '" << name << "'. File is of unsupported format version" << std::endl;
                return false;
            }
            if (err == Library::Error::UnsupportedFormatNamed) {
                std::cout << "cppcheck: Failed to load library configuration file '" << name << "'. File is of unsupported format version '" << badRoot << "'" << std::endl;
                return false;
            }
            loaded = true;
            break;
        }

        if (!loaded) {
            if (trace)
                std::cout << "library not found: '" << name << "'" << std::endl;
            std::cout << "cppcheck: Failed to load library configuration file '" << name << "'. File not found" << std::endl;
            if (name == "std.cfg") {
                std::cout << "Failed to load std.cfg. Your Cppcheck installation is broken, please re-install. "
                    "The Cppcheck binary was compiled with FILESDIR set to \"" CPPCHECK_FILESDIR
                    "\" and will therefore search for std.cfg in " CPPCHECK_FILESDIR "/cfg." << std::endl;
            }
            return false;
        }
    }
    return true;
}

int CppCheckExecutor::run()
{
    lookupConfigFile();

    if (!loadLibraries())
        return 1;

    const std::vector<FileEntry> files = FileLister::collect(mPathNames, mSettings.ignoredPaths, mSettings.fileFilters);
    if (files.empty()) {
        for (const std::string& path : mPathNames) {
            if (path.empty())
                std::cout << "cppcheck: no path specified" << std::endl;
        }
        std::cout << "cppcheck: error: could not find or open any of the paths given." << std::endl;
        return 1;
    }

    std::ofstream outputFile;
    if (!mSettings.outputFile.empty())
        outputFile.open(mSettings.outputFile);
    std::ostream& errStream = mSettings.outputFile.empty() ? std::cerr : outputFile;

    ErrorLogger logger(mSettings, std::cout, errStream);
    logger.reportHeader();

    CppCheck cppcheck(mSettings, mLibrary, logger);

    long long totalSize = 0;
    for (const FileEntry& file : files)
        totalSize += file.size;

    long long processedSize = 0;
    unsigned int index = 0;
    for (const FileEntry& file : files) {
        ++index;
        if (!mSettings.quiet && !mSettings.preprocessOnly)
            logger.reportOut("Checking " + file.path + " ...");

        cppcheck.check(file.path);

        processedSize += file.size;
        if (!mSettings.quiet && !mSettings.preprocessOnly && files.size() > 1) {
            std::ostringstream os;
            os << index << '/' << files.size() << " files checked "
               << (totalSize > 0 ? static_cast<int>((100LL * processedSize) / totalSize) : 0)
               << "% done";
            logger.reportOut(os.str());
        }
    }

    cppcheck.finish();
    logger.reportFooter();

    if (logger.hasErrors() && mSettings.exitCode != 0)
        return mSettings.exitCode;
    return 0;
}

