#include "preprocessor.h"

#include <algorithm>
#include <cctype>
#include <cstdlib>
#include <fstream>
#include <sstream>

#include "path.h"

namespace {
    bool isNameStart(char c)
    {
        return std::isalpha(static_cast<unsigned char>(c)) || c == '_' || c == '$';
    }

    bool isNameChar(char c)
    {
        return std::isalnum(static_cast<unsigned char>(c)) || c == '_' || c == '$';
    }

    std::string trim(const std::string& text)
    {
        std::string::size_type first = text.find_first_not_of(" \t\r\n");
        if (first == std::string::npos)
            return "";
        std::string::size_type last = text.find_last_not_of(" \t\r\n");
        return text.substr(first, last - first + 1);
    }

    /** Directive name of a line, empty when the line is not a directive. */
    std::string directiveName(const std::string& line)
    {
        const std::string text = trim(line);
        if (text.empty() || text[0] != '#')
            return "";
        std::string::size_type pos = 1;
        while (pos < text.size() && std::isspace(static_cast<unsigned char>(text[pos])))
            ++pos;
        std::string name;
        while (pos < text.size() && std::isalpha(static_cast<unsigned char>(text[pos])))
            name += text[pos++];
        return name;
    }

    std::string directiveArgument(const std::string& line)
    {
        const std::string text = trim(line);
        std::string::size_type pos = text.find('#') + 1;
        while (pos < text.size() && std::isspace(static_cast<unsigned char>(text[pos])))
            ++pos;
        while (pos < text.size() && std::isalpha(static_cast<unsigned char>(text[pos])))
            ++pos;
        return trim(text.substr(pos));
    }

    /** Split code into preprocessing tokens. */
    std::vector<std::string> splitTokens(const std::string& code)
    {
        std::vector<std::string> tokens;
        for (std::string::size_type i = 0; i < code.size();) {
            const char c = code[i];
            if (std::isspace(static_cast<unsigned char>(c))) {
                ++i;
                continue;
            }
            if (isNameStart(c)) {
                std::string name;
                while (i < code.size() && isNameChar(code[i]))
                    name += code[i++];
                tokens.push_back(name);
                continue;
            }
            if (std::isdigit(static_cast<unsigned char>(c)) ||
                (c == '.' && i + 1 < code.size() && std::isdigit(static_cast<unsigned char>(code[i + 1])))) {
                std::string number;
                while (i < code.size() && (std::isalnum(static_cast<unsigned char>(code[i])) || code[i] == '.' ||
                                           ((code[i] == '+' || code[i] == '-') && !number.empty() &&
                                            (number.back() == 'e' || number.back() == 'E')))) {
                    number += code[i++];
                }
                tokens.push_back(number);
                continue;
            }
            if (c == '"' || c == '\'') {
                std::string literal(1, code[i++]);
                while (i < code.size()) {
                    if (code[i] == '\\' && i + 1 < code.size()) {
                        literal += code[i++];
                        literal += code[i++];
                        continue;
                    }
                    literal += code[i];
                    if (code[i] == c) {
                        ++i;
                        break;
                    }
                    ++i;
                }
                tokens.push_back(literal);
                continue;
            }
            // multi character operators
            static const char * const operators[] = {
                "<<=", ">>=", "...", "->*", "<=>",
                "==", "!=", "<=", ">=", "&&", "||", "++", "--", "->", "::", "<<", ">>",
                "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=", ".*"
            };
            bool matched = false;
            for (const char * const op : operators) {
                const std::string opStr = op;
                if (code.compare(i, opStr.size(), opStr) == 0) {
                    tokens.push_back(opStr);
                    i += opStr.size();
                    matched = true;
                    break;
                }
            }
            if (matched)
                continue;
            tokens.emplace_back(1, code[i++]);
        }
        return tokens;
    }

    /** Expand macros in a token sequence. */
    std::string expandMacros(const std::string& code, const std::map<std::string, MacroDefinition>& macros, int depth = 0)
    {
        if (depth > 20)
            return code;

        std::string result;
        bool expanded = false;
        for (std::string::size_type i = 0; i < code.size();) {
            if (code[i] == '"' || code[i] == '\'') {
                const char quote = code[i];
                result += code[i++];
                while (i < code.size()) {
                    if (code[i] == '\\' && i + 1 < code.size()) {
                        result += code[i++];
                        result += code[i++];
                        continue;
                    }
                    result += code[i];
                    if (code[i++] == quote)
                        break;
                }
                continue;
            }
            if (!isNameStart(code[i])) {
                result += code[i++];
                continue;
            }
            std::string name;
            const std::string::size_type start = i;
            while (i < code.size() && isNameChar(code[i]))
                name += code[i++];

            const auto it = macros.find(name);
            if (it == macros.end()) {
                result += name;
                continue;
            }

            const MacroDefinition& macro = it->second;
            if (!macro.functionLike) {
                result += ' ';
                result += macro.body;
                expanded = true;
                continue;
            }

            // gather the arguments
            std::string::size_type pos = i;
            while (pos < code.size() && std::isspace(static_cast<unsigned char>(code[pos])))
                ++pos;
            if (pos >= code.size() || code[pos] != '(') {
                result += name;
                continue;
            }
            ++pos;
            std::vector<std::string> args;
            std::string current;
            int parens = 0;
            bool closed = false;
            for (; pos < code.size(); ++pos) {
                const char c = code[pos];
                if (c == '(')
                    ++parens;
                if (c == ')') {
                    if (parens == 0) {
                        closed = true;
                        ++pos;
                        break;
                    }
                    --parens;
                }
                if (c == ',' && parens == 0) {
                    args.push_back(trim(current));
                    current.clear();
                    continue;
                }
                current += c;
            }
            if (!closed) {
                result += code.substr(start, i - start);
                continue;
            }
            if (!trim(current).empty() || !args.empty())
                args.push_back(trim(current));

            std::string body;
            for (std::string::size_type b = 0; b < macro.body.size();) {
                if (!isNameStart(macro.body[b])) {
                    body += macro.body[b++];
                    continue;
                }
                std::string word;
                while (b < macro.body.size() && isNameChar(macro.body[b]))
                    word += macro.body[b++];
                const auto param = std::find(macro.parameters.begin(), macro.parameters.end(), word);
                if (param != macro.parameters.end()) {
                    const size_t index = static_cast<size_t>(param - macro.parameters.begin());
                    body += (index < args.size()) ? args[index] : std::string();
                } else {
                    body += word;
                }
            }
            result += ' ';
            result += body;
            i = pos;
            expanded = true;
        }

        return expanded ? expandMacros(result, macros, depth + 1) : result;
    }

    /** Evaluate a #if expression. Unknown identifiers count as 0. */
    long long evaluate(const std::vector<std::string>& tokens, size_t& pos, int minPrecedence);

    long long evaluatePrimary(const std::vector<std::string>& tokens, size_t& pos)
    {
        if (pos >= tokens.size())
            return 0;
        const std::string token = tokens[pos];
        if (token == "(") {
            ++pos;
            const long long value = evaluate(tokens, pos, 0);
            if (pos < tokens.size() && tokens[pos] == ")")
                ++pos;
            return value;
        }
        if (token == "!") {
            ++pos;
            return evaluatePrimary(tokens, pos) == 0 ? 1 : 0;
        }
        if (token == "-") {
            ++pos;
            return -evaluatePrimary(tokens, pos);
        }
        if (token == "+") {
            ++pos;
            return evaluatePrimary(tokens, pos);
        }
        if (token == "~") {
            ++pos;
            return ~evaluatePrimary(tokens, pos);
        }
        ++pos;
        if (!token.empty() && std::isdigit(static_cast<unsigned char>(token[0]))) {
            std::string digits;
            for (const char c : token) {
                if (std::isalnum(static_cast<unsigned char>(c)))
                    digits += c;
            }
            while (!digits.empty() && (digits.back() == 'u' || digits.back() == 'U' || digits.back() == 'l' || digits.back() == 'L'))
                digits.pop_back();
            if (digits.empty())
                return 0;
            return std::strtoll(digits.c_str(), nullptr, 0);
        }
        if (!token.empty() && token[0] == '\'')
            return token.size() > 2 ? static_cast<unsigned char>(token[1]) : 0;
        return 0;
    }

    int precedenceOf(const std::string& op)
    {
        if (op == "||")
            return 1;
        if (op == "&&")
            return 2;
        if (op == "|")
            return 3;
        if (op == "^")
            return 4;
        if (op == "&")
            return 5;
        if (op == "==" || op == "!=")
            return 6;
        if (op == "<" || op == ">" || op == "<=" || op == ">=")
            return 7;
        if (op == "<<" || op == ">>")
            return 8;
        if (op == "+" || op == "-")
            return 9;
        if (op == "*" || op == "/" || op == "%")
            return 10;
        return 0;
    }

    long long apply(const std::string& op, long long lhs, long long rhs)
    {
        if (op == "||")
            return (lhs || rhs) ? 1 : 0;
        if (op == "&&")
            return (lhs && rhs) ? 1 : 0;
        if (op == "|")
            return lhs | rhs;
        if (op == "^")
            return lhs ^ rhs;
        if (op == "&")
            return lhs & rhs;
        if (op == "==")
            return lhs == rhs;
        if (op == "!=")
            return lhs != rhs;
        if (op == "<")
            return lhs < rhs;
        if (op == ">")
            return lhs > rhs;
        if (op == "<=")
            return lhs <= rhs;
        if (op == ">=")
            return lhs >= rhs;
        if (op == "<<")
            return lhs << (rhs & 63);
        if (op == ">>")
            return lhs >> (rhs & 63);
        if (op == "+")
            return lhs + rhs;
        if (op == "-")
            return lhs - rhs;
        if (op == "*")
            return lhs * rhs;
        if (op == "/")
            return rhs == 0 ? 0 : lhs / rhs;
        if (op == "%")
            return rhs == 0 ? 0 : lhs % rhs;
        return 0;
    }

    long long evaluate(const std::vector<std::string>& tokens, size_t& pos, int minPrecedence)
    {
        long long lhs = evaluatePrimary(tokens, pos);
        while (pos < tokens.size()) {
            const std::string op = tokens[pos];
            const int precedence = precedenceOf(op);
            if (precedence == 0 || precedence < minPrecedence)
                break;
            ++pos;
            const long long rhs = evaluate(tokens, pos, precedence + 1);
            lhs = apply(op, lhs, rhs);
        }
        return lhs;
    }

    /** Replace defined(X) / defined X by 1 or 0. */
    std::string resolveDefined(const std::string& expression, const std::map<std::string, MacroDefinition>& macros)
    {
        std::string result;
        const std::vector<std::string> tokens = splitTokens(expression);
        for (size_t i = 0; i < tokens.size(); ++i) {
            if (tokens[i] != "defined") {
                result += tokens[i];
                result += ' ';
                continue;
            }
            size_t j = i + 1;
            bool paren = false;
            if (j < tokens.size() && tokens[j] == "(") {
                paren = true;
                ++j;
            }
            if (j < tokens.size()) {
                result += (macros.find(tokens[j]) != macros.end()) ? "1 " : "0 ";
                i = j;
                if (paren && i + 1 < tokens.size() && tokens[i + 1] == ")")
                    ++i;
            }
        }
        return result;
    }
}

bool Preprocessor::readFile(const std::string& filename, std::vector<std::string>& lines) const
{
    std::ifstream fin(filename, std::ios::binary);
    if (!fin.is_open())
        return false;

    std::ostringstream buffer;
    buffer << fin.rdbuf();
    std::string data = buffer.str();

    // split into lines, dropping '\r'
    std::vector<std::string> raw;
    std::string current;
    for (const char c : data) {
        if (c == '\n') {
            if (!current.empty() && current.back() == '\r')
                current.pop_back();
            raw.push_back(current);
            current.clear();
        } else {
            current += c;
        }
    }
    if (!current.empty())
        raw.push_back(current);

    // remove comments, keeping the line structure intact
    bool inBlockComment = false;
    for (std::string& line : raw) {
        std::string out;
        for (std::string::size_type i = 0; i < line.size();) {
            if (inBlockComment) {
                if (line.compare(i, 2, "*/") == 0) {
                    inBlockComment = false;
                    i += 2;
                } else {
                    ++i;
                }
                continue;
            }
            if (line.compare(i, 2, "//") == 0)
                break;
            if (line.compare(i, 2, "/*") == 0) {
                inBlockComment = true;
                out += ' ';
                i += 2;
                continue;
            }
            if (line[i] == '"' || line[i] == '\'') {
                const char quote = line[i];
                out += line[i++];
                while (i < line.size()) {
                    if (line[i] == '\\' && i + 1 < line.size()) {
                        out += line[i++];
                        out += line[i++];
                        continue;
                    }
                    out += line[i];
                    if (line[i++] == quote)
                        break;
                }
                continue;
            }
            out += line[i++];
        }
        line = out;
    }

    // join continuation lines but keep the number of lines
    for (size_t i = 0; i < raw.size(); ++i) {
        while (!raw[i].empty() && raw[i].back() == '\\' && i + 1 < raw.size()) {
            raw[i].pop_back();
            raw[i] += raw[i + 1];
            raw[i + 1].clear();
            raw.erase(raw.begin() + static_cast<long>(i) + 1);
            raw.insert(raw.begin() + static_cast<long>(i) + 1, "");
        }
    }

    lines = raw;
    return true;
}

std::set<std::string> Preprocessor::getConfigurationMacros(const std::vector<std::string>& lines) const
{
    std::set<std::string> defined;
    std::set<std::string> configs;

    for (const std::string& line : lines) {
        const std::string directive = directiveName(line);
        if (directive.empty())
            continue;
        const std::string argument = directiveArgument(line);
        if (directive == "define") {
            std::string name;
            for (const char c : argument) {
                if (!isNameChar(c))
                    break;
                name += c;
            }
            defined.insert(name);
        } else if (directive == "ifdef" || directive == "ifndef") {
            std::string name;
            for (const char c : argument) {
                if (!isNameChar(c))
                    break;
                name += c;
            }
            if (!name.empty() && defined.find(name) == defined.end())
                configs.insert(name);
        } else if (directive == "if" || directive == "elif") {
            const std::vector<std::string> tokens = splitTokens(argument);
            for (size_t i = 0; i < tokens.size(); ++i) {
                if (tokens[i] != "defined")
                    continue;
                size_t j = i + 1;
                if (j < tokens.size() && tokens[j] == "(")
                    ++j;
                if (j < tokens.size() && isNameStart(tokens[j][0]) && defined.find(tokens[j]) == defined.end())
                    configs.insert(tokens[j]);
            }
        }
    }

    for (const std::string& name : defined)
        configs.erase(name);
    return configs;
}

std::vector<std::string> Preprocessor::getConfigurations(const std::vector<std::string>& lines) const
{
    std::vector<std::string> result;
    result.emplace_back("");
    for (const std::string& macro : getConfigurationMacros(lines))
        result.push_back(macro + "=" + macro);
    return result;
}

std::vector<PreprocessedLine> Preprocessor::preprocess(const std::string& filename,
                                                       const std::vector<std::string>& lines,
                                                       const std::string& configuration,
                                                       std::set<std::string>& missingIncludes) const
{
    std::map<std::string, MacroDefinition> macros;

    auto defineMacro = [&macros](const std::string& text) {
        MacroDefinition macro;
        std::string::size_type pos = 0;
        while (pos < text.size() && isNameChar(text[pos]))
            macro.name += text[pos++];
        if (macro.name.empty())
            return;
        if (pos < text.size() && text[pos] == '(') {
            macro.functionLike = true;
            ++pos;
            std::string parameter;
            while (pos < text.size() && text[pos] != ')') {
                if (text[pos] == ',') {
                    macro.parameters.push_back(trim(parameter));
                    parameter.clear();
                } else {
                    parameter += text[pos];
                }
                ++pos;
            }
            if (!trim(parameter).empty())
                macro.parameters.push_back(trim(parameter));
            if (pos < text.size())
                ++pos;
        }
        macro.body = trim(text.substr(pos));
        macros[macro.name] = macro;
    };

    // -D definitions
    std::string::size_type pos = 0;
    while (pos < mSettings.userDefines.size()) {
        const std::string::size_type semi = mSettings.userDefines.find(';', pos);
        std::string define = mSettings.userDefines.substr(pos, semi == std::string::npos ? std::string::npos : semi - pos);
        const std::string::size_type eq = define.find('=');
        if (eq != std::string::npos)
            define = define.substr(0, eq) + " " + define.substr(eq + 1);
        defineMacro(define);
        if (semi == std::string::npos)
            break;
        pos = semi + 1;
    }

    // the configuration is a ';' separated list of NAME=VALUE
    pos = 0;
    while (pos < configuration.size()) {
        const std::string::size_type semi = configuration.find(';', pos);
        std::string define = configuration.substr(pos, semi == std::string::npos ? std::string::npos : semi - pos);
        const std::string::size_type eq = define.find('=');
        if (eq != std::string::npos)
            define = define.substr(0, eq) + " " + define.substr(eq + 1);
        defineMacro(define);
        if (semi == std::string::npos)
            break;
        pos = semi + 1;
    }

    for (const std::string& name : mSettings.userUndefs)
        macros.erase(name);

    struct ConditionalState {
        bool active;
        bool taken;
    };
    std::vector<ConditionalState> stack;
    auto active = [&stack]() {
        for (const ConditionalState& state : stack) {
            if (!state.active)
                return false;
        }
        return true;
    };

    std::vector<PreprocessedLine> result;
    for (size_t index = 0; index < lines.size(); ++index) {
        const std::string& line = lines[index];
        const std::string directive = directiveName(line);
        PreprocessedLine out;
        out.line = static_cast<int>(index) + 1;
        out.file = filename;

        if (!directive.empty()) {
            const std::string argument = directiveArgument(line);
            if (directive == "ifdef" || directive == "ifndef") {
                std::string name;
                for (const char c : argument) {
                    if (!isNameChar(c))
                        break;
                    name += c;
                }
                bool value = macros.find(name) != macros.end();
                if (directive == "ifndef")
                    value = !value;
                stack.push_back({value, value});
            } else if (directive == "if") {
                const std::string resolved = resolveDefined(argument, macros);
                const std::vector<std::string> tokens = splitTokens(expandMacros(resolved, macros));
                size_t p = 0;
                const bool value = evaluate(tokens, p, 0) != 0;
                stack.push_back({value, value});
            } else if (directive == "elif") {
                if (!stack.empty()) {
                    if (stack.back().taken) {
                        stack.back().active = false;
                    } else {
                        const std::string resolved = resolveDefined(argument, macros);
                        const std::vector<std::string> tokens = splitTokens(expandMacros(resolved, macros));
                        size_t p = 0;
                        const bool value = evaluate(tokens, p, 0) != 0;
                        stack.back().active = value;
                        stack.back().taken = value;
                    }
                }
            } else if (directive == "else") {
                if (!stack.empty()) {
                    stack.back().active = !stack.back().taken;
                    stack.back().taken = true;
                }
            } else if (directive == "endif") {
                if (!stack.empty())
                    stack.pop_back();
            } else if (active() && directive == "define") {
                defineMacro(argument);
            } else if (active() && directive == "undef") {
                std::string name;
                for (const char c : argument) {
                    if (!isNameChar(c))
                        break;
                    name += c;
                }
                macros.erase(name);
            } else if (active() && directive == "include") {
                std::string included;
                if (!argument.empty() && (argument[0] == '"' || argument[0] == '<')) {
                    const char close = (argument[0] == '"') ? '"' : '>';
                    const std::string::size_type end = argument.find(close, 1);
                    if (end != std::string::npos)
                        included = argument.substr(1, end - 1);
                }
                if (!included.empty()) {
                    bool found = false;
                    std::vector<std::string> candidates;
                    if (argument[0] == '"')
                        candidates.push_back(Path::getPath(filename) + included);
                    for (const std::string& dir : mSettings.includePaths)
                        candidates.push_back(dir + included);
                    for (const std::string& candidate : candidates) {
                        if (Path::isFile(candidate)) {
                            found = true;
                            break;
                        }
                    }
                    if (!found)
                        missingIncludes.insert(included);
                }
            }
            out.code.clear();
            result.push_back(out);
            continue;
        }

        if (!active()) {
            result.push_back(out);
            continue;
        }

        out.code = expandMacros(line, macros);
        result.push_back(out);
    }

    return result;
}

