// Token list built from the preprocessed code.

#ifndef TOKENIZE_H
#define TOKENIZE_H

#include <string>
#include <vector>

#include "preprocessor.h"

struct Token {
    std::string str;
    int line = 0;
    int column = 0;
    std::string file;
    /** Index of the matching bracket for (), [], {} - -1 when there is none. */
    int link = -1;

    bool isName() const;
