bool Token::isName() const
{
    return !str.empty() && isNameStart(str[0]);
}

bool Token::isNumber() const
{
    return !str.empty() && std::isdigit(static_cast<unsigned char>(str[0]));
}

bool Token::isKeyword() const
{
    return keywords().find(str) != keywords().end();
}

bool Token::isStandardType() const
{
    return standardTypes().find(str) != standardTypes().end();
}

void TokenList::createTokens(const std::vector<PreprocessedLine>& lines)
{
    static const char * const operators[] = {
        "<<=", ">>=", "...", "->*", "<=>",
        "==", "!=", "<=", ">=", "&&", "||", "++", "--", "->", "::", "<<", ">>",
        "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=", ".*"
    };

    for (const PreprocessedLine& line : lines) {
        const std::string& code = line.code;
        for (std::string::size_type i = 0; i < code.size();) {
            if (std::isspace(static_cast<unsigned char>(code[i]))) {
                ++i;
                continue;
            }
            Token token;
            token.line = line.line;
            token.column = static_cast<int>(i) + 1;
            token.file = line.file;

            if (isNameStart(code[i])) {
                while (i < code.size() && isNameChar(code[i]))
                    token.str += code[i++];
            } else if (std::isdigit(static_cast<unsigned char>(code[i])) ||
                       (code[i] == '.' && i + 1 < code.size() && std::isdigit(static_cast<unsigned char>(code[i + 1])))) {
                bool hex = false;
                while (i < code.size()) {
                    const char c = code[i];
                    if (std::isalnum(static_cast<unsigned char>(c)) || c == '.') {
                        if (c == 'x' || c == 'X')
                            hex = true;
                        token.str += c;
                        ++i;
                        continue;
                    }
                    if ((c == '+' || c == '-') && !hex && !token.str.empty() &&
                        (token.str.back() == 'e' || token.str.back() == 'E')) {
                        token.str += c;
                        ++i;
                        continue;
                    }
                    break;
                }
            } else if (code[i] == '"' || code[i] == '\'') {
                const char quote = code[i];
                token.str += code[i++];
                while (i < code.size()) {
                    if (code[i] == '\\' && i + 1 < code.size()) {
                        token.str += code[i++];
                        token.str += code[i++];
                        continue;
                    }
                    token.str += code[i];
                    if (code[i++] == quote)
                        break;
                }
            } else {
                bool matched = false;
                for (const char * const op : operators) {
                    const size_t length = std::strlen(op);
                    if (code.compare(i, length, op) == 0) {
                        token.str = op;
                        i += length;
                        matched = true;
                        break;
                    }
                }
                if (!matched)
                    token.str = std::string(1, code[i++]);
            }

            mTokens.push_back(std::move(token));
        }
    }
}

bool TokenList::createLinks(std::string& errorMessage, int& errorLine, int& errorColumn)
{
    std::vector<size_t> stack;
    for (size_t i = 0; i < mTokens.size(); ++i) {
        const std::string& str = mTokens[i].str;
        if (str == "(" || str == "[" || str == "{") {
            stack.push_back(i);
            continue;
        }
        if (str != ")" && str != "]" && str != "}")
            continue;
        if (stack.empty()) {
            errorMessage = "Unmatched '" + str + "'.";
            errorLine = mTokens[i].line;
            errorColumn = mTokens[i].column;
            return false;
        }
        const size_t open = stack.back();
        const std::string& openStr = mTokens[open].str;
        const bool ok = (openStr == "(" && str == ")") || (openStr == "[" && str == "]") ||
                        (openStr == "{" && str == "}");
        if (!ok) {
            errorMessage = "Unmatched '" + openStr + "'. Configuration: ''.";
            errorLine = mTokens[open].line;
            errorColumn = mTokens[open].column;
            return false;
        }
        stack.pop_back();
        mTokens[open].link = static_cast<int>(i);
        mTokens[i].link = static_cast<int>(open);
    }

    if (!stack.empty()) {
        const size_t open = stack.back();
        errorMessage = "Unmatched '" + mTokens[open].str + "'. Configuration: ''.";
        errorLine = mTokens[open].line;
        errorColumn = mTokens[open].column;
        return false;
    }
    return true;
}

