#include "checks.h"

#include <cstdlib>
#include <map>
#include <set>

namespace {
    /** Numeric value of an integer literal token, false when it is not one. */
    bool integerValue(const Token& token, long long& value)
    {
        if (!token.isNumber())
            return false;
        std::string text = token.str;
        if (text.find('.') != std::string::npos || text.find('e') != std::string::npos ||
            text.find('E') != std::string::npos) {
            // floating point literals are not interesting here
            if (text.find('x') == std::string::npos && text.find('X') == std::string::npos)
                return false;
        }
        while (!text.empty() && (text.back() == 'u' || text.back() == 'U' || text.back() == 'l' || text.back() == 'L'))
            text.pop_back();
        if (text.empty())
            return false;
        char *end = nullptr;
        value = std::strtoll(text.c_str(), &end, 0);
        return end != nullptr && *end == '\0';
    }

    ErrorMessage makeMessage(const CheckContext& ctx,
                             const Token& token,
                             const std::string& id,
                             Severity severity,
                             const std::string& text,
                             unsigned int cwe,
                             const std::string& info)
    {
        ErrorMessage msg(id, severity, text, cwe);
        ErrorLocation loc;
        loc.file = ctx.file;
        loc.line = token.line;
        loc.column = token.column;
        loc.info = info;
        msg.locations.push_back(loc);
        return msg;
    }

    /** True when the token starts a declaration of a simple type. */
    bool isTypeToken(const Token& token)
    {
        return token.isStandardType() || token.str == "const" || token.str == "static" ||
               token.str == "struct" || token.str == "unsigned" || token.str == "signed";
    }
}

void Checks::divisionByZero(const CheckContext& ctx)
{
    const std::vector<Token>& tokens = ctx.tokens.tokens();
    for (size_t i = 1; i + 1 < tokens.size(); ++i) {
        if (tokens[i].str != "/" && tokens[i].str != "%" && tokens[i].str != "/=" && tokens[i].str != "%=")
            continue;
        long long value = 0;
        if (!integerValue(tokens[i + 1], value) || value != 0)
            continue;
        // "a / 0.0" is not an integer division by zero
        if (tokens[i + 1].str.find('.') != std::string::npos)
            continue;
        ctx.report(makeMessage(ctx, tokens[i], "zerodiv", Severity::error, "Division by zero.", 369, "Division by zero"));
    }
}

void Checks::arrayIndexOutOfBounds(const CheckContext& ctx)
{
    const std::vector<Token>& tokens = ctx.tokens.tokens();

    // remember the declared size of local arrays
    std::map<std::string, long long> arraySize;
    for (size_t i = 0; i + 3 < tokens.size(); ++i) {
        if (!tokens[i].isStandardType() && tokens[i].str != "struct")
            continue;
        size_t name = i + 1;
        while (name < tokens.size() && (tokens[name].isStandardType() || tokens[name].str == "*"))
            ++name;
        if (name + 3 >= tokens.size() || !tokens[name].isName() || tokens[name].isKeyword())
            continue;
        if (tokens[name + 1].str != "[")
            continue;
        long long size = 0;
        if (!integerValue(tokens[name + 2], size) || tokens[name + 3].str != "]")
            continue;
        if (size > 0)
            arraySize[tokens[name].str] = size;
    }

    if (arraySize.empty())
        return;

    for (size_t i = 0; i + 2 < tokens.size(); ++i) {
        if (!tokens[i].isName() || tokens[i + 1].str != "[")
            continue;
        const auto it = arraySize.find(tokens[i].str);
        if (it == arraySize.end())
            continue;
        // skip the declaration itself
        if (i > 0 && (tokens[i - 1].isStandardType() || tokens[i - 1].str == "*"))
            continue;
        long long index = 0;
        if (!integerValue(tokens[i + 2], index) || tokens[i + 3].str != "]")
            continue;
        if (index < it->second)
            continue;
        const std::string text = "Array '" + it->first + "[" + std::to_string(it->second) + "]' accessed at index " +
                                 std::to_string(index) + ", which is out of bounds.";
        ErrorMessage msg = makeMessage(ctx, tokens[i + 1], "arrayIndexOutOfBounds", Severity::error, text, 788,
                                       "Array index out of bounds");
        ctx.report(msg);
    }
}

void Checks::unusedVariables(const CheckContext& ctx)
{
    if (!ctx.settings.isEnabled(Severity::style))
        return;

    const std::vector<Token>& tokens = ctx.tokens.tokens();

    struct VarInfo {
        size_t declaration = 0;
        bool assigned = false;
        bool read = false;
        bool isArray = false;
        bool addressTaken = false;
    };

    // only look at function bodies
    for (size_t i = 0; i < tokens.size(); ++i) {
        if (tokens[i].str != "{" || tokens[i].link < 0)
            continue;
        // a function body is preceded by ')'
        if (i == 0 || tokens[i - 1].str != ")")
            continue;

        const size_t bodyEnd = static_cast<size_t>(tokens[i].link);
        std::map<std::string, VarInfo> variables;
        std::vector<std::string> order;

        for (size_t j = i + 1; j < bodyEnd; ++j) {
            // declaration: <type> [*] name [= ...] ;
            if (!isTypeToken(tokens[j]))
                continue;
