            info.declaration = name;
            info.isArray = (next == "[");
            info.assigned = (next == "=");
            variables[tokens[name].str] = info;
            order.push_back(tokens[name].str);
            j = name;
        }

        for (size_t j = i + 1; j < bodyEnd; ++j) {
            const auto it = variables.find(tokens[j].str);
            if (it == variables.end() || j == it->second.declaration)
                continue;
            if (j > i + 1 && tokens[j - 1].str == "&")
                it->second.addressTaken = true;
            const std::string& next = tokens[j + 1].str;
            const bool isAssignment = (next == "=" && tokens[j + 2].str != "=");
