void Checks::nullPointerDereference(const CheckContext& ctx)
{
    const std::vector<Token>& tokens = ctx.tokens.tokens();

    // "p = 0 ; ... * p" in the same scope
    for (size_t i = 0; i + 4 < tokens.size(); ++i) {
        if (!tokens[i].isStandardType() && tokens[i].str != "void")
            continue;
        if (tokens[i + 1].str != "*" || !tokens[i + 2].isName())
            continue;
        if (tokens[i + 3].str != "=")
            continue;
