                             (integerValue(tokens[i + 4], value) && value == 0));
        if (!isNull || tokens[i + 5].str != ";")
            continue;

        const std::string name = tokens[i + 2].str;
        for (size_t j = i + 6; j + 1 < tokens.size(); ++j) {
            if (tokens[j].str == "}")
