                                           "Null pointer dereference: " + name, 476, "Null pointer dereference");
            msg.symbolNames.push_back(name);
            ctx.report(msg);
            break;
        }
    }
}

void Checks::collectFunctions(const CheckContext& ctx,
                              std::vector<FoundFunction>& defined,
                              std::vector<std::string>& called)
{
    const std::vector<Token>& tokens = ctx.tokens.tokens();

    for (size_t i = 0; i + 2 < tokens.size(); ++i) {
        if (!tokens[i].isName() || tokens[i].isKeyword())
            continue;
        if (tokens[i + 1].str != "(" || tokens[i + 1].link < 0)
            continue;
        const size_t closing = static_cast<size_t>(tokens[i + 1].link);
        const std::string after = ctx.tokens.at(closing + 1);

        // a definition is followed by '{' and preceded by a type
        const bool hasType = (i > 0) && (tokens[i - 1].isStandardType() || tokens[i - 1].str == "*" ||
                                         tokens[i - 1].isName());
        if (after == "{" && hasType) {
            FoundFunction func;
            func.name = tokens[i].str;
            func.line = tokens[i].line;
            func.column = tokens[i].column;
            for (size_t j = (i > 3 ? i - 3 : 0); j < i; ++j) {
                if (tokens[j].str == "static")
