void Checks::divisionByZero(const CheckContext& ctx)
{
    const std::vector<Token>& tokens = ctx.tokens.tokens();
    for (size_t i = 1; i + 1 < tokens.size(); ++i) {
        if (tokens[i].str != "/" && tokens[i].str != "%" && tokens[i].str != "/=" && tokens[i].str != "%=")
            continue;
