}

void Checks::arrayIndexOutOfBounds(const CheckContext& ctx)
{
    const std::vector<Token>& tokens = ctx.tokens.tokens();

    // remember the declared size of local arrays
    std::map<std::string, long long> arraySize;
    for (size_t i = 0; i + 3 < tokens.size(); ++i) {
