            }
            std::cout.flush();
            continue;
        }

        if (mSettings.checks.missingInclude) {
            for (const PreprocessedLine& line : code) {
                (void)line;
            }
            // the include directives were removed from the code, so scan the raw text
            for (size_t i = 0; i < lines.size(); ++i) {
                const std::string& raw = lines[i];
                const std::string::size_type hash = raw.find('#');
                if (hash == std::string::npos)
                    continue;
                if (raw.compare(hash + 1, 7, "include") != 0)
                    continue;
                std::string::size_type pos = hash + 8;
                while (pos < raw.size() && std::isspace(static_cast<unsigned char>(raw[pos])))
                    ++pos;
                if (pos >= raw.size() || (raw[pos] != '"' && raw[pos] != '<'))
                    continue;
                const char close = (raw[pos] == '"') ? '"' : '>';
                const std::string::size_type end = raw.find(close, pos + 1);
                if (end == std::string::npos)
                    continue;
                const std::string name = raw.substr(pos + 1, end - pos - 1);
                if (missingIncludes.find(name) == missingIncludes.end())
                    continue;

                ErrorMessage msg;
                msg.severity = Severity::information;
                if (close == '>') {
                    msg.id = "missingIncludeSystem";
                    msg.shortMessage = "Include file: <" + name + "> not found. Please note: Standard library headers do not need to be provided to get proper results.";
                } else {
                    msg.id = "missingInclude";
                    msg.shortMessage = "Include file: \"" + name + "\" not found.";
                }
                msg.verboseMessage = msg.shortMessage;
                ErrorLocation loc;
                loc.file = filename;
                loc.line = static_cast<int>(i) + 1;
                loc.column = static_cast<int>(hash) + 2;
                msg.locations.push_back(loc);
                report(msg, filename);
            }
        }

        if (mSettings.checkConfig)
            continue;

        checkConfiguration(filename, code, configuration);
    }
}

void CppCheck::checkConfiguration(const std::string& filename,
                                  const std::vector<PreprocessedLine>& code,
                                  const std::string& configuration)
{
    TokenList tokens;
    tokens.createTokens(code);

    std::string errorMessage;
    int errorLine = 0;
    int errorColumn = 0;
    if (!tokens.createLinks(errorMessage, errorLine, errorColumn)) {
        ErrorMessage msg("syntaxError", Severity::error, errorMessage);
        if (msg.shortMessage.find("Configuration") == std::string::npos)
            msg.shortMessage += " Configuration: '" + configuration + "'.";
        msg.verboseMessage = msg.shortMessage;
        ErrorLocation loc;
        loc.file = filename;
        loc.line = errorLine;
        loc.column = errorColumn;
        msg.locations.push_back(loc);
        report(msg, filename);
        return;
    }

    CheckContext ctx{mSettings, mLibrary, tokens, filename,
                     [this, &filename](const ErrorMessage& msg) {
                         report(msg, filename);
                     }};

    Checks::divisionByZero(ctx);
    Checks::arrayIndexOutOfBounds(ctx);
    Checks::nullPointerDereference(ctx);
    Checks::unusedVariables(ctx);

    if (mSettings.checks.unusedFunction) {
        std::vector<FoundFunction> defined;
        std::vector<std::string> called;
        Checks::collectFunctions(ctx, defined, called);
        for (const FoundFunction& func : defined) {
            FunctionInfo info;
            info.name = func.name;
            info.file = filename;
            info.line = func.line;
            info.column = func.column;
            info.isStatic = func.isStatic;
            mFunctions.push_back(info);
        }
        for (const std::string& name : called)
            mUsedFunctions.insert(name);
    }
}

void CppCheck::finish()
{
    if (mSettings.checks.unusedFunction) {
        for (const FunctionInfo& func : mFunctions) {
            if (func.name == "main" || func.isStatic)
                continue;
            if (mUsedFunctions.find(func.name) != mUsedFunctions.end())
                continue;
            ErrorMessage msg("unusedFunction", Severity::style,
                             "The function '" + func.name + "' is never used.", 561);
            ErrorLocation loc;
            loc.file = func.file;
            loc.line = func.line;
            loc.column = func.column;
            msg.locations.push_back(loc);
            report(msg, func.file);
        }
    }

    if (mSettings.isEnabled(Severity::information)) {
        int active = 40;
        if (mSettings.isEnabled(Severity::style))
            active += 60;
        if (mSettings.isEnabled(Severity::warning))
            active += 13;
        if (mSettings.checks.unusedFunction)
            active += 1;

        ErrorMessage msg("checkersReport", Severity::information,
                         "Active checkers: " + std::to_string(active) + "/" + std::to_string(totalCheckers) +
                         (mSettings.checkersReportFilename.empty()
                          ? " (use --checkers-report=<filename> to see details)"
                          : ""));
        ErrorLocation loc;
        loc.file = "nofile";
        msg.locations.push_back(loc);
        mLogger.reportErr(msg);
    }
}

