namespace {
    /** Minimal JSON reader, enough for a compile database. */
    struct JsonValue {
        enum class Type { Null, Bool, Number, String, Array, Object } type = Type::Null;
        std::string text;
        std::vector<JsonValue> items;
        std::vector<std::pair<std::string, JsonValue>> members;

        const JsonValue *member(const std::string& key) const {
            for (const auto& entry : members) {
                if (entry.first == key)
                    return &entry.second;
            }
            return nullptr;
        }
    };

    class JsonParser {
    public:
        explicit JsonParser(const std::string& data) : mData(data) {}

        bool parse(JsonValue& value) {
            skipSpace();
            if (!parseValue(value))
                return false;
            skipSpace();
            return true;
        }

    private:
        void skipSpace() {
            while (mPos < mData.size() && std::isspace(static_cast<unsigned char>(mData[mPos])))
                ++mPos;
        }

        bool parseValue(JsonValue& value) {
            if (mPos >= mData.size())
                return false;
            const char c = mData[mPos];
            if (c == '{')
                return parseObject(value);
            if (c == '[')
                return parseArray(value);
            if (c == '"') {
                value.type = JsonValue::Type::String;
                return parseString(value.text);
            }
            if (mData.compare(mPos, 4, "true") == 0) {
                value.type = JsonValue::Type::Bool;
                value.text = "true";
                mPos += 4;
                return true;
            }
            if (mData.compare(mPos, 5, "false") == 0) {
                value.type = JsonValue::Type::Bool;
                value.text = "false";
                mPos += 5;
                return true;
            }
            if (mData.compare(mPos, 4, "null") == 0) {
                value.type = JsonValue::Type::Null;
                mPos += 4;
                return true;
            }
            if (c == '-' || std::isdigit(static_cast<unsigned char>(c))) {
                value.type = JsonValue::Type::Number;
                while (mPos < mData.size() && (std::isalnum(static_cast<unsigned char>(mData[mPos])) ||
                                               mData[mPos] == '-' || mData[mPos] == '+' || mData[mPos] == '.')) {
                    value.text += mData[mPos++];
                }
                return true;
            }
            return false;
        }

        bool parseString(std::string& result) {
            if (mPos >= mData.size() || mData[mPos] != '"')
                return false;
            ++mPos;
            while (mPos < mData.size() && mData[mPos] != '"') {
                if (mData[mPos] == '\\' && mPos + 1 < mData.size()) {
                    ++mPos;
                    switch (mData[mPos]) {
                    case 'n':
                        result += '\n';
                        break;
                    case 't':
                        result += '\t';
                        break;
                    case 'r':
                        result += '\r';
                        break;
                    default:
                        result += mData[mPos];
                    }
                    ++mPos;
                    continue;
                }
                result += mData[mPos++];
            }
            if (mPos >= mData.size())
                return false;
            ++mPos;
            return true;
        }

        bool parseArray(JsonValue& value) {
            value.type = JsonValue::Type::Array;
            ++mPos;
            skipSpace();
            if (mPos < mData.size() && mData[mPos] == ']') {
                ++mPos;
                return true;
            }
            for (;;) {
                JsonValue item;
                skipSpace();
                if (!parseValue(item))
                    return false;
                value.items.push_back(std::move(item));
                skipSpace();
                if (mPos < mData.size() && mData[mPos] == ',') {
                    ++mPos;
                    continue;
                }
                if (mPos < mData.size() && mData[mPos] == ']') {
                    ++mPos;
                    return true;
                }
                return false;
            }
        }

        bool parseObject(JsonValue& value) {
            value.type = JsonValue::Type::Object;
            ++mPos;
            skipSpace();
            if (mPos < mData.size() && mData[mPos] == '}') {
                ++mPos;
                return true;
            }
            for (;;) {
                skipSpace();
                std::string key;
                if (!parseString(key))
                    return false;
                skipSpace();
                if (mPos >= mData.size() || mData[mPos] != ':')
                    return false;
                ++mPos;
                skipSpace();
                JsonValue item;
                if (!parseValue(item))
                    return false;
                value.members.emplace_back(key, std::move(item));
                skipSpace();
                if (mPos < mData.size() && mData[mPos] == ',') {
                    ++mPos;
                    continue;
                }
                if (mPos < mData.size() && mData[mPos] == '}') {
                    ++mPos;
                    return true;
                }
                return false;
            }
        }

        const std::string& mData;
        std::string::size_type mPos = 0;
    };

    std::string readWholeFile(const std::string& filename, bool& ok)
    {
        std::ifstream fin(filename, std::ios::binary);
        ok = fin.is_open();
        if (!ok)
            return "";
        std::ostringstream buffer;
        buffer << fin.rdbuf();
        return buffer.str();
    }

    /** Split a command line into arguments, honouring quotes. */
    std::vector<std::string> splitCommand(const std::string& command)
    {
        std::vector<std::string> result;
        std::string current;
        char quote = '\0';
        for (const char c : command) {
            if (quote != '\0') {
                if (c == quote)
                    quote = '\0';
                else
                    current += c;
                continue;
            }
            if (c == '"' || c == '\'') {
                quote = c;
                continue;
            }
            if (std::isspace(static_cast<unsigned char>(c))) {
                if (!current.empty()) {
                    result.push_back(current);
                    current.clear();
                }
                continue;
            }
            current += c;
        }
        if (!current.empty())
            result.push_back(current);
        return result;
    }
}

Project::Result Project::importCompileDatabase(const std::string& filename, std::string& message)
{
    bool ok = false;
    const std::string data = readWholeFile(filename, ok);
    if (!ok) {
        message = "failed to open compilation database '" + filename + "'";
        return Result::Error;
    }

    JsonValue root;
    JsonParser parser(data);
    if (!parser.parse(root) || root.type != JsonValue::Type::Array) {
        message = "compilation database is not a JSON array";
        return Result::Error;
    }

    for (const JsonValue& entry : root.items) {
        if (entry.type != JsonValue::Type::Object) {
            message = "compilation database is not a JSON array";
            return Result::Error;
        }
        const JsonValue *directory = entry.member("directory");
        if (!directory || directory->type != JsonValue::Type::String) {
            message = "'directory' field in compilation database entry missing";
            return Result::Error;
        }
        const JsonValue *file = entry.member("file");
        if (!file || file->type != JsonValue::Type::String) {
            message = "'file' field in compilation database entry missing";
            return Result::Error;
        }
        const JsonValue *command = entry.member("command");
        const JsonValue *arguments = entry.member("arguments");
        if (!command && !arguments) {
            message = "no 'arguments' or 'command' field found in compilation database entry";
            return Result::Error;
        }

        std::vector<std::string> args;
        if (arguments && arguments->type == JsonValue::Type::Array) {
            for (const JsonValue& argument : arguments->items)
                args.push_back(argument.text);
        } else if (command) {
            args = splitCommand(command->text);
        }

        ProjectFileEntry projectFile;
        projectFile.path = file->text;
        if (!projectFile.path.empty() && projectFile.path[0] != '/')
            projectFile.path = Path::simplify(directory->text + "/" + projectFile.path);

        for (const std::string& argument : args) {
            if (argument.compare(0, 2, "-D") == 0 && argument.size() > 2) {
                if (!projectFile.defines.empty())
                    projectFile.defines += ';';
                projectFile.defines += argument.substr(2);
            } else if (argument.compare(0, 2, "-I") == 0 && argument.size() > 2) {
                projectFile.includePaths.push_back(argument.substr(2));
            }
        }
        mFiles.push_back(projectFile);
    }
    return Result::Ok;
}

Project::Result Project::importSolution(const std::string& filename, std::string& message)
{
    bool ok = false;
    const std::string data = readWholeFile(filename, ok);
    if (!ok || data.find("Microsoft Visual Studio Solution File") == std::string::npos) {
        message = "Visual Studio solution file header not found";
        return Result::Error;
    }

    // "Project(...) = "name", "path", "guid"" - the second string is the path
    std::string::size_type pos = 0;
    while ((pos = data.find("Project(", pos)) != std::string::npos) {
        const std::string::size_type eol = data.find('\n', pos);
        const std::string line = data.substr(pos, eol == std::string::npos ? std::string::npos : eol - pos);
        std::vector<std::string> strings;
        std::string::size_type quote = 0;
        while ((quote = line.find('"', quote)) != std::string::npos) {
            const std::string::size_type end = line.find('"', quote + 1);
            if (end == std::string::npos)
                break;
            strings.push_back(line.substr(quote + 1, end - quote - 1));
            quote = end + 1;
        }
        if (strings.size() >= 2) {
            ProjectFileEntry entry;
            entry.path = Path::simplify(Path::getPath(filename) + Path::toNativeSeparators(strings[1]));
            mFiles.push_back(entry);
        }
        pos = (eol == std::string::npos) ? data.size() : eol;
    }
    return Result::Ok;
}

Project::Result Project::importXmlProject(const std::string& filename, const char *kind, std::string& message)
{
    bool ok = false;
    const std::string data = readWholeFile(filename, ok);
    if (!ok) {
        message = std::string(kind) + " is not a valid XML - XML_ERROR_FILE_NOT_FOUND";
        return Result::Error;
    }

    XmlDocument doc;
    if (!doc.parse(data) || !doc.root()) {
        message = std::string(kind) + " is not a valid XML - XML_ERROR_PARSING_TEXT";
        return Result::Error;
    }

    // collect anything that looks like a source file reference
    std::vector<const XmlNode *> queue{doc.root()};
    while (!queue.empty()) {
        const XmlNode *node = queue.back();
        queue.pop_back();
        for (const XmlNode& child : node->children)
            queue.push_back(&child);
        for (const auto& attribute : node->attributes) {
            const std::string value = Path::toNativeSeparators(attribute.second);
            if (Path::acceptFile(value)) {
                ProjectFileEntry entry;
                entry.path = Path::simplify(Path::getPath(filename) + value);
                mFiles.push_back(entry);
            }
        }
        if (!node->text.empty()) {
            const std::string value = Path::toNativeSeparators(node->text);
            if (Path::acceptFile(value)) {
                ProjectFileEntry entry;
                entry.path = Path::simplify(Path::getPath(filename) + value);
                mFiles.push_back(entry);
            }
        }
    }
    return Result::Ok;
}

Project::Result Project::import(const std::string& filename, Settings& settings, std::string& message)
{
    (void)settings;
    const std::string ext = Path::getExtension(filename);
    if (ext == ".json")
        return importCompileDatabase(filename, message);
    if (ext == ".sln")
        return importSolution(filename, message);
    if (ext == ".vcxproj")
        return importXmlProject(filename, "Visual Studio project file", message);
    if (ext == ".bpr")
        return importXmlProject(filename, "Borland project file", message);
    if (ext == ".cppcheck")
        return importXmlProject(filename, "Cppcheck GUI project file", message);
    return Result::UnknownFormat;
}

