namespace {
    /** Minimal JSON reader, enough for a compile database. */
    struct JsonValue {
        enum class Type { Null, Bool, Number, String, Array, Object } type = Type::Null;
        std::string text;
        std::vector<JsonValue> items;
        std::vector<std::pair<std::string, JsonValue>> members;

        const JsonValue *member(const std::string& key) const {
            for (const auto& entry : members) {
                if (entry.first == key)
                    return &entry.second;
            }
            return nullptr;
        }
    };

    class JsonParser {
    public:
        explicit JsonParser(const std::string& data) : mData(data) {}

        bool parse(JsonValue& value) {
            skipSpace();
            if (!parseValue(value))
                return false;
            skipSpace();
            return true;
        }

    private:
        void skipSpace() {
            while (mPos < mData.size() && std::isspace(static_cast<unsigned char>(mData[mPos])))
                ++mPos;
        }

        bool parseValue(JsonValue& value) {
            if (mPos >= mData.size())
                return false;
            const char c = mData[mPos];
            if (c == '{')
                return parseObject(value);
            if (c == '[')
                return parseArray(value);
            if (c == '"') {
                value.type = JsonValue::Type::String;
                return parseString(value.text);
            }
            if (mData.compare(mPos, 4, "true") == 0) {
                value.type = JsonValue::Type::Bool;
                value.text = "true";
                mPos += 4;
                return true;
            }
            if (mData.compare(mPos, 5, "false") == 0) {
                value.type = JsonValue::Type::Bool;
                value.text = "false";
                mPos += 5;
