            }
            if (mData.compare(mPos, 4, "null") == 0) {
                value.type = JsonValue::Type::Null;
                mPos += 4;
                return true;
            }
            if (c == '-' || std::isdigit(static_cast<unsigned char>(c))) {
                value.type = JsonValue::Type::Number;
