            }
            return false;
        }

        bool parseString(std::string& result) {
            if (mPos >= mData.size() || mData[mPos] != '"')
                return false;
            ++mPos;
            while (mPos < mData.size() && mData[mPos] != '"') {
                if (mData[mPos] == '\\' && mPos + 1 < mData.size()) {
                    ++mPos;
                    switch (mData[mPos]) {
                    case 'n':
                        result += '\n';
                        break;
                    case 't':
                        result += '\t';
                        break;
                    case 'r':
                        result += '\r';
                        break;
                    default:
                        result += mData[mPos];
                    }
                    ++mPos;
                    continue;
                }
                result += mData[mPos++];
            }
            if (mPos >= mData.size())
                return false;
            ++mPos;
            return true;
        }

        bool parseArray(JsonValue& value) {
            value.type = JsonValue::Type::Array;
            ++mPos;
            skipSpace();
            if (mPos < mData.size() && mData[mPos] == ']') {
                ++mPos;
                return true;
            }
            for (;;) {
                JsonValue item;
                skipSpace();
                if (!parseValue(item))
                    return false;
                value.items.push_back(std::move(item));
                skipSpace();
                if (mPos < mData.size() && mData[mPos] == ',') {
                    ++mPos;
                    continue;
                }
                if (mPos < mData.size() && mData[mPos] == ']') {
                    ++mPos;
                    return true;
                }
                return false;
            }
        }

        bool parseObject(JsonValue& value) {
            value.type = JsonValue::Type::Object;
            ++mPos;
            skipSpace();
            if (mPos < mData.size() && mData[mPos] == '}') {
                ++mPos;
                return true;
            }
